INSERT INTO `agent_decision_log` VALUES (42, 45, 85, '回答这个问题', '### 迟到认定与处罚标准\n\n**认定标准**\n- 超过 9:00 打卡，即记为迟到。[1]\n\n**处罚标准**\n- 迟到 30 分钟以内：每次扣款 30 元。[1]\n- 迟到 30 分钟至 60 分钟：每次扣款 60 元。[1]\n- 迟到超过 60 分钟：按半天事假处理。[1]\n\n**豁免与加重情形**\n- 月度累计迟到三次以内，且每次不超过 10 分钟：予以豁免，不扣款、不通报。[1]\n- 月度迟到累计达到五次：当月绩效考核得分扣减 5 分，并计入年度评优负面清单。[1]\n\n> 注：早退（18:00 前打卡离岗且未履行请假手续）的处理标准与迟到相同。[1]', '[{\"step\": 1, \"type\": \"router\", \"detail\": \"正在判断问题类型 → 知识问答（附图问答，图中要点：迟到是怎么认定和处罚的？）\", \"payload\": {\"intent\": \"kb_qa\", \"confidence\": 0.95, \"has_images\": true, \"vision_note\": \"迟到是怎么认定和处罚的？\"}, \"elapsed_ms\": 1612}, {\"step\": 2, \"type\": \"rewrite\", \"detail\": \"拆解为 2 个子问题\", \"payload\": {\"hyde_used\": false, \"sub_queries\": [\"迟到的认定标准是什么？\", \"迟到的处罚措施是什么？\"], \"rewritten_query\": \"迟到是怎么认定和处罚的？\"}, \"elapsed_ms\": 2238}, {\"step\": 3, \"type\": \"retrieve\", \"detail\": \"向量语义检索：命中 5 条\", \"payload\": {\"source\": \"vector\", \"hit_count\": 5}, \"elapsed_ms\": 563}, {\"step\": 3, \"type\": \"retrieve\", \"detail\": \"关键词 BM25 检索：命中 5 条\", \"payload\": {\"source\": \"keyword\", \"hit_count\": 5}, \"elapsed_ms\": 0}, {\"step\": 4, \"type\": \"grade\", \"detail\": \"相关度 10.0 ✓ 通过\", \"payload\": {\"score\": 10.0, \"reason\": \"检索片段[1]完整界定了迟到认定时间及处罚措施，直接支撑问题的完整回答。\", \"verdict\": \"pass\"}, \"elapsed_ms\": 2139}, {\"step\": 6, \"type\": \"generate\", \"detail\": \"答案生成完成（283 字）\", \"payload\": {\"chars\": 283}, \"elapsed_ms\": 4075}, {\"step\": 6, \"type\": \"reflect\", \"detail\": \"自检通过 ✓\", \"payload\": {\"round\": 1, \"result\": \"pass\"}, \"elapsed_ms\": 1189}, {\"step\": 7, \"type\": \"citation\", \"detail\": \"引用 1 条出处\", \"payload\": {\"citations\": [{\"chunk_no\": 3, \"doc_name\": \"员工考勤与休假管理制度\", \"section_path\": \"第三章 考勤打卡\"}]}, \"elapsed_ms\": 0}]', 1, 11895, '2026-08-24 12:38:51');
INSERT INTO `chat_message` VALUES (55, 30, 'user', '产品研发中心下设哪几个组，各自负责什么？', NULL, NULL, NULL, '2026-08-24 11:57:22');
INSERT INTO `chat_message` VALUES (56, 30, 'assistant', '根据知识库内容[1]，产品研发中心下设六个二级部门，职责如下：\n\n- **平台架构组**（32人）：负责技术中台、微服务治理、公共组件与基础设施研发，维护服务注册中心、配置中心与消息队列[1]\n- **应用研发组**（56人）：负责核心业务系统的前后端研发，按产品线划分为三个敏捷小组，两周一个迭代[1]\n- **算法组**（28人）：负责机器学习、自然语言处理与检索算法研发，支撑智能问答与推荐产品线[1]\n- **数据平台组**（24人）：负责数据仓库建设、ETL流水线、BI报表与数据治理[1]\n- **测试组**（20人）：负责功能测试、自动化测试、性能测试与发布验证，维护自动化回归用例库[1]\n- **运维组**（8人）：负责生产环境部署、监控告警、容量规划与故障应急响应，实行7×24值班制[1]', '[{\"chunk_no\": 3, \"doc_name\": \"公司组织架构与部门职责\", \"section_path\": \"公司组织架构与部门职责/二、各部门职责\"}]', NULL, 28, '2026-08-24 11:57:32');
