INSERT INTO `chat_message` VALUES (85, 45, 'assistant', '### 迟到认定与处罚标准\n\n**认定标准**\n- 超过 9:00 打卡，即记为迟到。[1]\n\n**处罚标准**\n- 迟到 30 分钟以内：每次扣款 30 元。[1]\n- 迟到 30 分钟至 60 分钟：每次扣款 60 元。[1]\n- 迟到超过 60 分钟：按半天事假处理。[1]\n\n**豁免与加重情形**\n- 月度累计迟到三次以内，且每次不超过 10 分钟：予以豁免，不扣款、不通报。[1]\n- 月度迟到累计达到五次：当月绩效考核得分扣减 5 分，并计入年度评优负面清单。[1]\n\n> 注：早退（18:00 前打卡离岗且未履行请假手续）的处理标准与迟到相同。[1]', '[{\"chunk_no\": 3, \"doc_name\": \"员工考勤与休假管理制度\", \"section_path\": \"第三章 考勤打卡\"}]', NULL, 42, '2026-08-24 12:38:51');
