INSERT INTO `kb_chunk` VALUES (48, '09aafc98-900d-4803-9642-eaee9964fdfc', 12, 1, '办公用品采购与领用规范/一、目的与适用范围', '办公用品采购与领用规范\n> 文档编号：ADMIN-OPS-2026-003 ｜ 版本：V3.0 ｜ 发布日期：2026-01-15 ｜ 责任部门：行政部\n一、目的与适用范围\n1.1 目的\n为规范公司办公用品的采购、库存、领用与报废管理，在保障办公需求的前提下控制行政成本，特制定本规范。本规范旨在实现：\n- 采购流程透明化，供应商选择有据可依；\n- 库存周转合理，常用物资不断档、不积压；\n- 领用行为可追溯，杜绝浪费与物资流失。\n1.2 适用范围\n本规范适用于公司总部及各分支机构的全体员工，覆盖办公文具、打印耗材、办公设备配件、清洁用品、茶水间物资等日常行政物资。办公电脑、显示器等 IT 资产按《IT 资产管理办法》另行管理，不在本规范范围内。', 202, '2026-08-24 11:36:27');
INSERT INTO `kb_chunk` VALUES (49, 'c638352f-6b8e-464f-9d10-28f777849d26', 12, 2, '办公用品采购与领用规范/二、物资分类目录', '二、物资分类目录\n2.1 分类编码规则\n办公用品按四级编码管理：大类-中类-小类-物资编号，例如 `A01-B02-C003-0012` 表示「文具类-书写工具-签字笔-黑色 0.5mm」。\n2.2 大类划分\n| 编码 | 大类名称 | 典型物资 | 领用方式 |\n| --- | --- | --- | --- |\n| A01 | 文具类 | 签字笔、笔记本、文件夹、订书机 | 自助领用 |\n| A02 | 纸张耗材 | A4 打印纸、复印纸、信封 | 自助领用 |\n| A03 | 打印耗材 | 硒鼓、墨盒、色带 | 审批领用 |\n| A04 | 桌面收纳 | 文件柜、笔筒、桌面置物架 | 审批领用 |\n| A05 | 茶水间物资 | 咖啡、茶包、纸杯、瓶装水 | 自助取用 |\n| A06 | 清洁用品 | 垃圾袋、纸巾、清洁剂 | 自助取用 |\n| A07 | 办公设备配件 | 键盘、鼠标、转接头、HDMI 线 | 审批领用 |\n2.3 耗材标准配置\n新员工入职标准文具包包含：签字笔 2 支、笔记本 1 本、便签纸 1 套、文件夹 3 个、订书机 1 个。部门可按岗位实际需求增配，需在入职物资申请单中注明。', 317, '2026-08-24 11:36:27');
INSERT INTO `kb_chunk` VALUES (50, '00e0b36d-57e3-4439-815a-23af371477ea', 12, 3, '办公用品采购与领用规范/三、采购管理', '三、采购管理\n3.1 采购申请\n各部门于每月 25 日前提报次月物资需求，通过行政管理系统填写《办公用品需求申请单》。零星补货由行政部库管员根据安全库存阈值自动触发，无需部门申请。\n3.2 库存阈值管理\n- **最低库存**：常用物资低于该值时系统自动生成补货提醒，如 A4 打印纸最低库存为 20 箱；\n- **最高库存**：补货后不得超过该值，避免资金占用，如签字笔最高库存为 500 支；\n- **补货周期**：常规物资每两周集中补货一次，紧急物资可发起紧急采购流程。\n3.3 供应商管理\n行政部通过比价方式选择供应商，遵循以下规则：\n1. 单次采购金额 2000 元以下：可直接向协议供应商下单；\n2. 单次采购金额 2000-10000 元：至少三家供应商比价，比价记录存档备查；\n3. 单次采购金额 10000 元以上：需行政部经理审批，并签订框架协议；\n4. 协议供应商每年评审一次，评分低于 70 分（满分 100）的终止合作。\n3.4 验收与入库\n物资到货后由库管员与申请人共同验收，核对品名、规格、数量与质量。验收通过后两个工作日内完成入库登记并拍照留档。验收不合格的物资由行政部负责退换货。', 314, '2026-08-24 11:36:27');
INSERT INTO `kb_chunk` VALUES (51, 'b6c9875b-b038-40d3-bb27-d15a380ca7e5', 12, 4, '办公用品采购与领用规范/四、领用管理', '四、领用管理\n4.1 领用方式\n- **自助领用**：A01、A02、A05、A06 类物资在行政系统自助下单，凭取件码至办公用品柜自助领取；\n- **审批领用**：A03、A04、A07 类物资需填写领用事由，经部门负责人审批后由库管员发放；\n- **批量领用**：单次领用金额超过 300 元的，需行政部经理加签。\n4.2 领用频次参考\n| 物资 | 建议频次 | 单次上限 |\n| --- | --- | --- |\n| A4 打印纸 | 每月 2 次 | 2 包/人 |\n| 签字笔 | 每季度 1 次 | 2 支/人 |\n| 便签纸 | 每季度 1 次 | 1 套/人 |\n| 硒鼓（按部门） | 按需 | 1 支/次 |\n超出参考频次的领用需求系统将提示说明原因，不强制拦截。\n4.3 以旧换新\n硒鼓、墨盒类耗材领用新件时须交回旧件，由行政部统一交由有资质的回收商处理，回收记录保存三年。键盘、鼠标等配件损坏的，须交回旧件方可领取新件，旧件由 IT 部门做数据清除后报废。', 274, '2026-08-24 11:36:27');
INSERT INTO `kb_chunk` VALUES (52, 'dfce6b47-65f7-46f0-9b65-9ad3c334d8c1', 12, 5, '办公用品采购与领用规范/五、盘点与报废', '五、盘点与报废\n5.1 盘点制度\n行政部每季度末组织一次全面盘点，年度末进行年度大盘点并由财务部监盘。盘点差异率超过 2% 的，须提交书面说明并查明原因。\n5.2 报废流程\n无法继续使用的物资由库管员登记造册，注明报废原因，经行政部经理审批后处理。涉及电子废弃物的，交由持有危废处理资质的厂商环保回收，严禁随意丢弃。', 98, '2026-08-24 11:36:27');
INSERT INTO `kb_chunk` VALUES (53, 'bd7db58b-dabf-46ef-9d47-aee4e44c3aaf', 12, 6, '办公用品采购与领用规范/六、成本分摊与考核', '六、成本分摊与考核\n办公用品成本按实际领用部门分摊，计入部门行政费用。行政部每月发布《办公用品消耗月报》，对异常消耗部门进行提示。年度办公用品费用预算执行率纳入部门行政管理评价，超支 15% 以上的部门需在年度总结中专项说明。', 70, '2026-08-24 11:36:27');
INSERT INTO `kb_chunk` VALUES (54, 'f2bd64de-8c1a-4493-926d-d39311eed044', 12, 7, '办公用品采购与领用规范/七、附则', '七、附则\n本规范由行政部负责解释与修订，自 2026 年 1 月 15 日起施行，原 V2.4 版本同时废止。员工对物资质量的投诉可直接反馈至行政服务邮箱，行政部承诺一个工作日内响应。', 57, '2026-08-24 11:36:27');
INSERT INTO `kb_chunk` VALUES (55, '07eabd46-5a74-40c9-8c8a-7ab4d3fd7354', 13, 1, '第一章 总则', '差旅费用报销管理办法\n文档编号：ADMIN-FIN-2026-002\n版本：V1.8\n发布日期：2026年2月10日\n适用范围：因公出差的全职员工\n第一章 总则\n第一条 为规范差旅费管理，明确费用标准与报销流程，兼顾成本控制与员工体验，制定本办法。\n第二条 差旅费是指员工经批准临时到常驻工作地以外的城市履行公务所发生的城市间交通费、住宿费、市内交通费、伙食补助费和公杂费。\n第三条 员工出差须提前三个工作日在 OA 系统提交出差申请，注明出差事由、目的地、行程安排与预算预估，经审批通过后方可订票出行。未经审批的出差，财务部不予报销。', 166, '2026-08-24 11:36:29');
INSERT INTO `kb_chunk` VALUES (56, 'e8e33371-1f48-4979-940b-bb9af4d4cfc2', 13, 2, '第二章 城市间交通标准', '第二章 城市间交通标准\n第四条 交通工具等级标准按员工职级执行。', 20, '2026-08-24 11:36:29');
INSERT INTO `kb_chunk` VALUES (57, 'db27933d-04b9-4450-b489-13eae9b34471', 13, 3, '一、高铁/动车：普通员工可乘坐二等座；经理级（M2 及以上）可乘坐一等座；总监级（M4 及以上）可乘坐商务座。', '一、高铁/动车：普通员工可乘坐二等座；经理级（M2 及以上）可乘坐一等座；总监级（M4 及以上）可乘坐商务座。\n二、飞机：单程飞行时间超过四小时或无高铁可达时，普通员工可乘坐经济舱；总监级及以上可乘坐公务舱。\n三、火车：普通员工硬卧，经理级软卧，总监级及以上软卧或高铁一等座。\n四、出差人员应优先选择折扣机票，提前七天以上预订。原则上不得购买全价经济舱及以上舱位，确因紧急公务需要的，须分管副总特批。\n第五条 交通预订统一通过公司差旅平台（合作供应商：携程商旅）预订，使用公司支付方式，无需个人垫资。特殊情况下自行购票的，凭发票与行程单报销。\n第六条 退改签费用。因公务变更导致的退改签费用可全额报销；因个人原因导致的退改签费用原则上由个人承担，特殊情况经部门负责人与财务部共同确认后可予报销。', 215, '2026-08-24 11:36:29');
INSERT INTO `kb_chunk` VALUES (58, '83bc60ca-0a8b-4534-8856-dfb9130e344c', 13, 4, '第三章 住宿费标准', '第三章 住宿费标准\n第七条 住宿费实行限额管理，按出差目的地城市分级与员工职级分档执行，限额为每人每晚上限。\n一、一线城市（北京、上海、广州、深圳）：普通员工 500 元，经理级 700 元，总监级及以上 1000 元。\n二、新一线及省会城市（杭州、成都、武汉、南京、西安等）：普通员工 400 元，经理级 600 元，总监级及以上 900 元。\n三、其他城市：普通员工 300 元，经理级 500 元，总监级及以上 800 元。\n第八条 住宿管理细则。\n一、同性别人士出差同一目的地的，原则上两人合住标准间，住宿限额按两人各自限额之和的 80% 执行。\n二、入住会议主办方统一安排酒店且价格超限额 20% 以内的，凭会议通知予以报销。\n三、住宿费以酒店开具的增值税发票报销，须注明入住人姓名、入住与离店日期。\n四、当日往返且末班车可返回的，原则上不安排住宿。', 236, '2026-08-24 11:36:29');
INSERT INTO `kb_chunk` VALUES (59, 'c13ec166-076e-4182-b525-a1519d9bc39c', 13, 5, '第四章 出差补助', '第四章 出差补助\n第九条 伙食补助按自然日计算，每人每天 100 元，出差目的地无需再按城市分档。会议统一安排用餐的，当天伙食补助减半；全天由客户方招待的，当天不再发放伙食补助。\n第十条 市内交通费与公杂费包干补助为每人每天 80 元，涵盖机场大巴、地铁、公交、出租车及通讯等杂费。往返机场的高铁/大巴费用可凭票据实报销，不计入包干额度。\n第十一条 补助天数计算规则。\n一、补助天数按出差自然日计算，含出发日与返回日。\n二、出差期间跨多个城市的，补助天数合并计算，不重复发放。\n三、乘坐晚间交通工具（20:00 至次日 5:00 期间乘车满六小时）未安排住宿的，另发放一夜住宿包干补助 150 元。', 185, '2026-08-24 11:36:29');
INSERT INTO `kb_chunk` VALUES (60, '44434443-9018-4f54-8fa3-ff6ac7e00be8', 13, 6, '第五章 报销流程', '第五章 报销流程\n第十二条 报销时限。差旅费应在返回后 15 个工作日内提交报销申请，超过 30 天未报销且无正当理由的，财务部有权拒绝受理。\n第十三条 报销材料清单。\n一、出差申请审批单（OA 系统自动关联）。\n二、机票行程单、火车票报销凭证、住宿发票等原始票据。\n三、会议通知、培训邀请函等佐证材料（如适用）。\n四、超标准事项的特批邮件或审批记录。\n第十四条 报销审批流程。\n一、报销人通过费控系统填写差旅报销单，上传票据影像，系统自动比对标准。\n二、部门负责人审核出差真实性，一至两个工作日内完成审批。\n三、财务共享中心复核票据合规性，两个工作日内完成复核。\n四、金额超过 20000 元的报销单，需财务总监加签审批。\n五、复核通过后，报销款于三个工作日内支付至员工工资卡。\n第十五条 票据合规要求。\n一、所有发票须为增值税发票（纸质或电子），抬头为公司全称，纳税人识别号正确。\n二、连号发票、开具日期与行程明显不符的发票，财务部将退回并要求说明。\n三、电子发票须查验防伪码真伪，重复报销电子发票的系统将自动拦截并通报审计。', 288, '2026-08-24 11:36:29');
INSERT INTO `kb_chunk` VALUES (61, '1c17f877-7dad-417a-9102-e456844d1857', 13, 7, '第六章 特殊情形处理', '第六章 特殊情形处理\n第十六条 考察调研、客户招待等发生的业务招待费不得混入差旅费报销，应单独填写业务招待费报销单，注明招待对象、人数与事由。\n第十七条 员工出差期间因病就医产生的医疗费用，凭医院票据通过补充医疗保险渠道理赔，不在差旅费中列支。\n第十八条 因客户原因导致的行程延长，须邮件报部门负责人确认，延长期间的住宿与补助按原标准执行；因个人原因滞留产生的费用自理。\n第十九条 自驾出差需提前审批，油费与过路费凭票实报实销，每公里补贴 0.8 元（含油费，不含过路费），行程以导航记录为准。乘车人不得再重复领取市内交通包干补助。', 165, '2026-08-24 11:36:29');
INSERT INTO `kb_chunk` VALUES (62, '122ec501-46b3-4612-8391-5d861d0d197e', 13, 8, '第七章 监督与问责', '第七章 监督与问责\n第二十条 财务部与内审部门每季度对差旅费报销进行抽样审计，抽样比例不低于 20%。查实虚假报销的，追回款项并按公司奖惩制度处理，情节严重的解除劳动合同。\n第二十一条 部门年度差旅预算执行率纳入部门负责人管理考核。超预算 10% 以上的部门，需向分管副总提交书面说明。', 89, '2026-08-24 11:36:29');
INSERT INTO `kb_chunk` VALUES (63, 'ff80ccfc-3e4d-44ee-b1b1-0816b6250d0c', 13, 9, '第八章 附则', '第八章 附则\n第二十二条 本办法由财务部负责解释，自 2026 年 2 月 10 日起施行。原 V1.7 版本同时废止。\n第二十三条 国外差旅费用标准参照《海外差旅管理细则》另行执行。', 57, '2026-08-24 11:36:29');
INSERT INTO `kb_chunk` VALUES (64, 'c762a433-8f2f-4293-a18e-7a18be16f8eb', 14, 1, '公司组织架构与部门职责/一、总体架构', '公司组织架构与部门职责\n> 文档编号：ADMIN-HR-2026-004 ｜ 版本：V5.2 ｜ 发布日期：2026-04-01 ｜ 批准人：总经理办公会\n一、总体架构\n公司实行「总经理—分管副总—部门—组」四级管理架构。截至 2026 年 3 月末，公司全员编制 486 人，其中总部 352 人，分支机构 134 人。组织架构每年年初随战略规划复盘调整一次，年中原则上不做结构性变动。\n1.1 一级部门设置\n| 序号 | 部门 | 编制 | 部门负责人 | 汇报对象 |\n| --- | --- | --- | --- | --- |\n| 1 | 产品研发中心 | 168 | 首席技术官（CTO） | 总经理 |\n| 2 | 产品设计部 | 36 | 设计总监 | CTO |\n| 3 | 市场营销部 | 52 | 市场总监 | 分管营销副总 |\n| 4 | 销售部 | 78 | 销售总监 | 分管营销副总 |\n| 5 | 客户成功部 | 41 | 客户成功总监 | 分管营销副总 |\n| 6 | 人力资源部 | 22 | 人力资源总监（HRD） | 总经理 |', 301, '2026-08-24 11:36:30');
INSERT INTO `kb_chunk` VALUES (65, '5c4aa05b-75f9-4e3c-9752-da8fa8ace996', 14, 2, '公司组织架构与部门职责/一、总体架构', '| 分管营销副总 |\n| 6 | 人力资源部 | 22 | 人力资源总监（HRD） | 总经理 |\n| 7 | 财务部 | 18 | 财务总监（CFO） | 总经理 |\n| 8 | 行政部 | 15 | 行政经理 | HRD |\n| 9 | 信息技术部（IT） | 24 | IT 经理 | CTO |\n| 10 | 法务合规部 | 9 | 法务总监 | 总经理 |\n| 11 | 质量管理部 | 23 | 质量总监 | CTO |', 134, '2026-08-24 11:36:30');
INSERT INTO `kb_chunk` VALUES (66, '48a742f0-6c97-48ee-9e00-5f76d0d392a8', 14, 3, '公司组织架构与部门职责/二、各部门职责', '二、各部门职责\n2.1 产品研发中心\n产品研发中心是公司核心产品与技术的研发主体，下设六个二级部门：\n1. **平台架构组**（32 人）：负责技术中台、微服务治理、公共组件与基础设施研发，维护服务注册中心、配置中心与消息队列；\n2. **应用研发组**（56 人）：负责核心业务系统的前后端研发，按产品线划分为三个敏捷小组，两周一个迭代；\n3. **算法组**（28 人）：负责机器学习、自然语言处理与检索算法研发，支撑智能问答与推荐产品线；\n4. **数据平台组**（24 人）：负责数据仓库建设、ETL 流水线、BI 报表与数据治理；\n5. **测试组**（20 人）：负责功能测试、自动化测试、性能测试与发布验证，维护自动化回归用例库；\n6. **运维组**（8 人）：负责生产环境部署、监控告警、容量规划与故障应急响应，实行 7×24 值班制。\n研发中心技术决策采用技术委员会机制，重大技术选型（如数据库更换、框架升级）须经技术委员会评审，评审通过后以技术规范形式发布全员执行。\n2.2 产品设计部\n产品设计部负责产品体验设计与用户研究，下设交互设计组、视觉设计组与用户研究组。', 306, '2026-08-24 11:36:30');
INSERT INTO `kb_chunk` VALUES (67, '220328f4-ffe5-435e-b1bc-e4c8e9586c76', 14, 4, '公司组织架构与部门职责/二、各部门职责', '2.2 产品设计部\n产品设计部负责产品体验设计与用户研究，下设交互设计组、视觉设计组与用户研究组。主要职责包括：产品原型与交互稿设计、设计规范维护、品牌视觉管理、可用性测试（每季度不少于四场）以及设计资产库建设。所有对外发布的界面元素必须使用设计资产库中的标准组件，新增组件需经设计评审会通过。\n2.3 市场营销部\n市场营销部负责品牌建设、市场活动、内容营销与线索获取，下设品牌组、活动组、数字营销组与市场合作组。年度市场费用预算为营业收入的 8%，其中数字营销投放占比不低于 60%。市场部对「有效线索量」「线索转化率」「获客成本（CAC）」三项指标负责，CAC 年度目标为不高于 3200 元/客户。\n2.4 销售部\n销售部按区域划分为华东、华北、华南、西部四个大区，另设战略客户组负责年度合同额 100 万元以上的大客户。销售部对签约金额、回款率与客户续约率负责，续约率年度目标为 85%。销售提成按季度核算，回款确认后随下季度工资发放。\n2.5 客户成功部\n客户成功部负责交付实施、客户培训、工单支持与续费挖掘，下设实施组、支持组与续费组。', 294, '2026-08-24 11:36:30');
INSERT INTO `kb_chunk` VALUES (68, 'bba394b9-5b13-4552-995a-5641d1ba9312', 14, 5, '公司组织架构与部门职责/二、各部门职责', '.5 客户成功部\n客户成功部负责交付实施、客户培训、工单支持与续费挖掘，下设实施组、支持组与续费组。工单响应时限承诺：P1 级故障 15 分钟内响应，P2 级 30 分钟内响应，P3/P4 级 2 小时内响应。客户满意度（CSAT）年度目标为 92 分以上。\n2.6 人力资源部\n人力资源部下设招聘组、培训发展组、薪酬绩效组与员工关系组。主要职责包括：年度人力规划、招聘交付、培训体系建设、薪酬福利核算、绩效考核组织与劳动风险管理。校园招聘集中在每年 9-11 月，社会招聘全年滚动进行，研发岗位平均到岗周期为 38 天。\n2.7 财务部\n财务部下设核算组、资金组、税务组与经营分析组。负责会计核算、资金管理、税务筹划、预算管理与经营分析报告。月度经营分析报告于每月 8 日前提交管理层。\n2.8 行政部\n行政部负责办公场地管理、资产管理、采购管理、车辆管理、前台接待与员工活动组织。行政服务台设在总部一层大堂，工作日 9:00-18:00 提供现场服务。\n2.9 信息技术部（IT）\nIT 部负责全员办公设备、内网系统、账号权限、信息安全与 IT 服务台。', 297, '2026-08-24 11:36:30');
INSERT INTO `kb_chunk` VALUES (69, 'bbb12863-0a13-455d-b96d-7a1cf4ca17ed', 14, 6, '公司组织架构与部门职责/二、各部门职责', '2.9 信息技术部（IT）\nIT 部负责全员办公设备、内网系统、账号权限、信息安全与 IT 服务台。新员工入职账号开通时限为一个工作日，设备故障处理时限为半个工作日。信息安全事务接受法务合规部的合规监督。\n2.10 法务合规部\n法务合规部负责合同审核、知识产权管理、纠纷处理、数据合规与监管对接。对外合同金额 5 万元以上的必须经法务审核；产品数据处理活动须通过法务合规部组织的数据合规评审。\n2.11 质量管理部\n质量管理部独立于研发中心，负责质量体系建设、过程审计、发布把关与客户质量反馈闭环。拥有产品发布一票否决权，发布评审未通过版本不得上线。', 170, '2026-08-24 11:36:30');
INSERT INTO `kb_chunk` VALUES (70, '58c5fde2-c0b6-4cd3-8b19-c73d115e8fa3', 14, 7, '公司组织架构与部门职责/三、跨部门协作机制', '三、跨部门协作机制\n3.1 部门职责边界争议处理\n当出现职责边界争议时，按以下顺序处理：先由相关部门经理协商；协商不成的提交分管副总裁定；涉及跨分管线的，提交总经理办公会裁决。裁定结果由人力资源部更新至本文件。\n3.2 重大项目虚拟团队\n涉及三个以上部门的项目设立虚拟项目组，实行项目Owner负责制。项目Owner由立项评审会任命，拥有跨部门资源协调权，项目奖金池由参与部门按贡献度分配。\n3.3 例会制度\n- 总经理办公会：每周一上午 9:30，副总级以上参加；\n- 经营分析会：每月第一个工作周，部门负责人以上参加；\n- 产品评审会：每周四下午 14:00，产品、设计、研发代表参加；\n- 全员大会：每季度末，全员参加。', 194, '2026-08-24 11:36:30');
INSERT INTO `kb_chunk` VALUES (71, 'a3ac471c-2b99-48c9-9257-81466bb142d1', 14, 8, '公司组织架构与部门职责/四、附则', '四、附则\n本文件由人力资源部负责维护，架构调整经总经理办公会批准后五个工作日内更新发布。员工如对部门职责存在疑问，可通过 OA 流程向人力资源部咨询。', 46, '2026-08-24 11:36:30');
INSERT INTO `kb_chunk` VALUES (72, 'b06edd1f-8050-491b-ae62-9442b2704657', 15, 1, '一、会议室总览', '会议室使用与行政服务指南\n一、会议室总览\n总部办公区共有会议室 18 间，覆盖三层办公楼层。全部会议室配置投屏（无线投屏器与 HDMI 线）、百兆有线网络口与访客 Wi-Fi。预订系统入口：OA 工作台「会议室预订」。\n1.1 会议室清单与容量\n一层：路演厅（120 人，含舞台与音响，用于全员大会）、培训室 A/B（各 40 人，可合并为 80 人）。二层：长江厅（20 人，视频会议专用，含全向麦克风与双屏）、黄河厅（16 人，圆桌）、泰山厅（12 人）、华山厅（12 人）。三层：衡山厅（8 人）、嵩山厅（8 人）、恒山厅（8 人）、恒山二厅（6 人）及散布各处的电话亭 8 个（1 人，隔音）。\n1.2 设备与耗材配置标准\n路演厅与长江厅配置专业技术支持，会议前需行政部设备值班员到场调试；其余会议室自助使用，故障报修扫描桌角二维码。各会议室标配白板笔（黑蓝红三色）与板擦，泰山厅及以上规格标配视频会议摄像头。', 254, '2026-08-24 11:36:30');
INSERT INTO `kb_chunk` VALUES (73, '7a192302-99f6-4fca-8b45-e2ccda987145', 15, 2, '二、预订规则', '二、预订规则\n预订开放时间为使用日前十四天早上八点，先到先得。单次预订默认一小时起订，路演厅需提前三个工作日申请并由行政部经理审批。每人每日累计预订不超过四小时，连续占用同一会议室不超过三小时（路演厅除外）。\n2.1 优先级与冲突处理\n客户接待与高管会议优先。当高优先级会议与已预订会议冲突时，行政部提前至少四小时与原预订人协调改期。同一时段多人抢订时，系统按提交顺序分配。\n2.2 爽约与清理\n预订开始后十五分钟未到场且无法联系上的，视为爽约，系统自动释放会议室；每月爽约三次的暂停预订权限七天。会议结束后请带走物品并擦净白板，杂物留置的由行政部拍照通报至部门群。', 175, '2026-08-24 11:36:30');
INSERT INTO `kb_chunk` VALUES (74, '717f604a-5416-4c19-80c5-f0dd9cc2766d', 15, 3, '三、使用规范', '三、使用规范\n会议室仅限公务使用，禁止存放个人物品过夜。涉密会议须使用一层的涉密会议室并登记参会人名单，会后检查白板与桌面无遗留内容。外部访客进入会议室须由接待人全程陪同，访客 Wi-Fi 与内网隔离。会议期间保持音量，路演厅音响使用不早于八点半、不晚于二十点，避免影响邻近办公区。', 87, '2026-08-24 11:36:30');
INSERT INTO `kb_chunk` VALUES (75, '4b14412f-9c22-4d88-bf90-65fdbcad6449', 15, 4, '四、行政服务窗口', '四、行政服务窗口\n4.1 服务内容与时限\n行政服务台位于总部一层大堂，工作日 9:00-18:00。主要服务：访客登记与接待（即时）、快递收发（当日入库，系统通知）、失物招领、办公用品应急领用、名片印制（三个工作日）、印章使用（按《印章管理办法》审批，紧急用印两小时内响应）。\n4.2 车辆与差旅支持\n公务用车提前半天在 OA 申请，市内用车优先调度新能源车；机场接送由行政部合作网约车企业账号直接下单，费用计入部门。出差票务统一通过差旅平台，紧急改签可联系行政值班手机。\n4.3 报修与建议\n办公环境报修（灯光、空调、桌椅、门禁）扫码提交工单，响应时限半个工作日；紧急情况（漏水、断电）直拨行政值班电话。对行政服务的建议可发至行政服务邮箱或每月行政开放日当面反馈，行政部承诺三个工作日内答复。', 215, '2026-08-24 11:36:30');
INSERT INTO `kb_chunk` VALUES (76, '4eb969ab-6a57-4a84-bf9c-9e12a6a63769', 15, 5, '五、附则', '五、附则\n本指南由行政部负责解释，设备清单与会议室平面图以 OA 知识库最新版本为准。更新日期：2026 年 5 月 10 日。', 40, '2026-08-24 11:36:30');
INSERT INTO `kb_chunk` VALUES (77, 'ca7068b9-22d4-4d3e-b29c-95164bfcc786', 16, 1, '第一章 总则', '员工考勤与休假管理制度\n文档编号：ADMIN-HR-2026-001\n版本：V2.3\n发布日期：2026年3月1日\n适用范围：全体正式员工、试用期员工、实习生\n第一章 总则\n第一条 为规范公司考勤管理，保障正常工作秩序，维护员工合法权益，依据《劳动法》《职工带薪年休假条例》等法律法规，结合公司实际情况，制定本制度。\n第二条 本制度适用于公司全体员工。外包人员、劳务派遣人员的考勤管理参照合作协议执行。\n第三条 考勤管理坚持公平、公正、公开原则，考勤数据作为薪资核算、绩效评定、评优评先的重要依据。', 154, '2026-08-24 11:36:31');
INSERT INTO `kb_chunk` VALUES (78, 'bc20cce3-8a46-4270-92e7-a63e6d17659e', 16, 2, '第二章 工作时间', '第二章 工作时间\n第四条 公司实行标准工时制，每周工作五天，周一至周五，每日工作八小时。\n一、上午工作时间：9:00-12:00，其中 8:55 前需完成上班打卡。\n二、下午工作时间：13:30-18:00，18:05 后方可进行下班打卡。\n三、午休时间：12:00-13:30，共计一个半小时。\n四、弹性缓冲：员工可在 8:30-9:00 之间到岗，相应地在 17:30-18:00 之间离岗，保证每日八小时有效工作时长。\n第五条 研发中心实行弹性工作制试点，核心工作时段为 10:00-16:00，员工需保证每日八小时工作时长，每月需在系统中提交至少 176 小时的有效工时。\n第六条 法定节假日按国务院办公厅通知执行。公司额外提供每年度三天全员福利假，通常安排在春节假期前后。', 211, '2026-08-24 11:36:31');
INSERT INTO `kb_chunk` VALUES (79, '63891834-6cf7-48d9-b822-f501f739e66e', 16, 3, '第三章 考勤打卡', '第三章 考勤打卡\n第七条 员工上下班须通过企业微信进行打卡，打卡方式包括 Wi-Fi 打卡与 GPS 定位打卡两种。\n一、Wi-Fi 打卡：连接办公区指定 Wi-Fi（SSID 为 Staff-Office）后打卡，有效范围为办公楼层。\n二、GPS 打卡：因公外出或拜访客户时，可在客户现场使用 GPS 打卡，定位偏差不得超过 500 米。\n三、打卡异常：因手机故障、系统故障等原因无法打卡的，应在两个工作日内提交补卡申请，每月补卡次数不超过三次，超出部分按缺卡处理。\n第八条 迟到与早退的认定标准如下。\n一、迟到：超过 9:00 打卡记为迟到。迟到 30 分钟以内，每次扣款 30 元；迟到 30 分钟至 60 分钟，每次扣款 60 元；迟到超过 60 分钟按半天事假处理。\n二、早退：18:00 前打卡离岗且未履行请假手续的记为早退，处理标准与迟到相同。\n三、月度累计迟到或早退三次以内且每次不超过 10 分钟的，予以豁免，不扣款不通报。\n四、月度迟到或早退累计达到五次，当月绩效考核得分扣减 5 分，并计入年度评优负面清单。\n第九条 旷工的认定与处理。\n一、未经批准擅自缺勤、请假逾期不归且未补办手续、拒不服从工作安排的，按旷工处理。\n二、旷工一天扣除当日工资的三倍，旷工半天按一天计算。\n三、月度累计旷工达三天，或年度累计旷工达五天，视为严重违反规章制度，公司有权解除劳动合同。', 368, '2026-08-24 11:36:31');
INSERT INTO `kb_chunk` VALUES (80, '9e65f9f1-a17f-409e-8372-b1ddddb1d186', 16, 4, '第四章 加班管理', '第四章 加班管理\n第十条 公司不提倡无效加班。确因工作需要加班的，须提前通过 OA 系统提交加班申请，经部门负责人批准后生效。\n第十一条 加班时长的计算与补偿。\n一、工作日加班：按 1.5 倍时薪计算加班费，或按 1:1 比例折算调休。\n二、休息日加班：优先安排调休，调休比例 1:1.5；无法调休的按两倍时薪计发加班费。\n三、法定节假日加班：按三倍时薪计发加班费，不得以调休替代。\n四、单次加班不足一小时的不计入加班时长；加班时长计算以打卡记录与审批单共同确认。\n第十二条 调休有效期为一个自然年，当年未使用的调休最迟可在次年第一季度末前休完，逾期自动清零。年度加班调休上限为 40 小时。', 184, '2026-08-24 11:36:31');
INSERT INTO `kb_chunk` VALUES (81, '6e2de386-4d48-4daa-b7f9-759747cf4a65', 16, 5, '第五章 休假管理', '第五章 休假管理\n第十三条 年休假。\n一、员工累计工作满 1 年不满 10 年的，年休假 5 天；满 10 年不满 20 年的，年休假 10 天；满 20 年的，年休假 15 天。\n二、入职满一年起享受年休假，当年度剩余日历天数折算确定，折算后不足一整天的部分不享受。\n三、年休假原则上当年使用，经审批可跨年结转至次年第一季度末。年休假期间工资福利待遇不变。\n第十四条 病假。\n一、病假需提供二级及以上医院出具的病假建议书、挂号单及诊断证明。\n二、病假工资按当地最低工资标准的 80% 发放，医疗期按国家规定执行。\n三、单次病假三天以内可由部门负责人审批；三天以上需人力资源部复核；连续病假超过五天需提交住院或复诊记录。\n第十五条 事假。\n一、事假为无薪假，按日扣除当日全额工资。\n二、事假一年累计不得超过 15 天，超过部分原则上不予批准。\n三、事假一天以内由部门负责人审批，一至三天需分管副总审批，三天以上需总经理审批。\n第十六条 婚假、产假、陪产假、丧假。\n一、婚假：依法登记结婚的员工享受婚假 10 天（含国家规定 3 天及地方奖励假），须在登记后一年内一次性休完。', 302, '2026-08-24 11:36:31');
INSERT INTO `kb_chunk` VALUES (82, 'f272b904-21b3-48d8-8b53-614c87605f37', 16, 6, '第五章 休假管理', '法登记结婚的员工享受婚假 10 天（含国家规定 3 天及地方奖励假），须在登记后一年内一次性休完。\n二、产假：女员工产假 158 天（含国家规定 98 天及地方奖励 60 天），难产增加 15 天，多胞胎每多一婴增加 15 天。\n三、陪产假：男员工在子女出生后可享受陪产假 15 天，须在产后六个月内使用。\n四、丧假：直系亲属（父母、配偶、子女）亡故的，丧假 5 天；祖父母、外祖父母、配偶父母亡故的，丧假 3 天。异地奔丧另给路途假 2 天。', 138, '2026-08-24 11:36:31');
INSERT INTO `kb_chunk` VALUES (83, 'ff2f5336-367b-4da0-acd6-3e546b7d3dff', 16, 7, '第六章 请销假流程', '第六章 请销假流程\n第十七条 请假审批权限一览。\n一、一天以内：部门负责人审批。\n二、一至三天：部门负责人审核，分管副总审批。\n三、三天至七天：部门负责人与分管副总审核，人力资源部审批。\n四、七天以上：逐级审核后报总经理审批。\n五、部门负责人请假由分管副总审批，副总级以上请假由总经理审批。\n第十八条 请假须提前通过 OA 系统提交申请。一天以内的请假应至少提前一个工作日申请；一天以上应至少提前三个工作日申请；年休假、婚假应提前七天申请。突发疾病等紧急情况可先口头报备，返岗后一个工作日内补办手续。\n第十九条 销假管理。假期结束后应在当日通过 OA 系统办理销假。假期届满仍需续假的，应在原假期结束前办理续假手续，续假按新的请假流程审批。未按时销假且未续假的，按旷工处理。', 209, '2026-08-24 11:36:31');
INSERT INTO `kb_chunk` VALUES (84, 'a9875e5a-5c15-4b66-baca-2aec4d162195', 16, 8, '第七章 附则', '第七章 附则\n第二十条 本制度由人力资源部负责解释与修订，每年复审一次。\n第二十一条 本制度自 2026 年 3 月 1 日起施行，原 V2.2 版本同时废止。执行过程中如与国家法律法规冲突，以国家规定为准。', 64, '2026-08-24 11:36:31');
INSERT INTO `kb_chunk` VALUES (85, '21b8bbdb-cd29-4b47-9431-509481840359', 17, 1, '第一章 文件信息', '员工手册：入职与试用期指引\n第一章 文件信息\n文档编号：ADMIN-HR-2026-005。版本：V6.0。发布日期：2026年4月20日。编制部门：人力\n资源部员工关系组。适用对象：新入职员工、用人部门导师、HRBP。', 68, '2026-08-24 11:36:32');
INSERT INTO `kb_chunk` VALUES (86, '2e2f741e-c4ce-451f-9396-6ebf2bc8e3a1', 17, 2, '第二章 入职前准备', '第二章 入职前准备\n一、Offer 发放与确认\n人力资源部在终面通过后三个工作日内发放电子\nOffer，候选人需在五个工作日内完成线上确认。逾期未确认视为自动放弃。背景调查在 Offer 确认\n后启动，常规岗位调查周期三至五个工作日，涉及资金、核心数据权限的岗位调查周期延长至十\n个工作日。\n二、入职材料清单\n新员工报到当日须携带：身份证原件及复印件两份、学历学位证书原件（校验后退回）、近\n期一寸免冠照片两张、原单位离职证明、体检报告（二级以上医院，报到日前三十天内有效）、\n银行卡复印件（用于工资代发）。材料不齐的，可先报到后补交，补交期限不超过入职后十个工\n作日；逾期未补视为提供虚假入职信息处理。\n三、入职通知\nHR 助理在报到日前三个工作日发送《入职指引邮件》，包含报到时间地点、联系人、着装建\n议与第一周日程安排。报到日前一天，用人部门导师须确认工位、办公电脑、门禁权限与账号申\n请工单已全部就绪。', 251, '2026-08-24 11:36:32');
INSERT INTO `kb_chunk` VALUES (87, '66c9c447-1653-4550-b74e-c7a54f8207c9', 17, 3, '第三章 报到与首周安排', '第三章 报到与首周安排\n一、报到日流程\n上午九点至总部一层行政服务台报到，随后依次完成：材料核验（三十分钟）、劳动合同与\n保密协议签署（六十分钟）、办公设备领取与账号激活（三十分钟）、部门入职见面会（六十分\n钟）。下午参加公司统一的新员工入职培训。\n二、首周日程\n第一天：公司文化与制度通识培训；第二天：信息安全与合规必修课（含考试，八十分合格\n，不合格可补考一次）；第三天：部门业务介绍与团队破冰；第四天：岗位工具链上手（代码仓\n库、OA、费控、工单系统）；第五天：与导师共同制定试用期目标计划并签字确认。', 157, '2026-08-24 11:36:32');
INSERT INTO `kb_chunk` VALUES (88, 'b0c182ba-af4b-4883-965f-c53dafad88c0', 17, 4, '第四章 试用期规定', '第四章 试用期规定\n一、试用期时长\n劳动合同期三个月以上不满一年的，试用期一个月；一年以上不满三年的，试用期二个月；\n三年以上固定期限及无固定期限合同，试用期六个月。公司与应届毕业生统一签订三年期合同，\n试用期六个月。试用期包含在劳动合同期限内。\n二、试用期薪酬与福利\n试用期工资为转正工资的百分之百，公司不设折扣试用期。试用期员工正常缴纳五险一金，\n享受法定福利与商业补充医疗保险；当年度年休假按入职日折算，于转正后可申请使用。\n三、试用期考核\n试用期考核分为月度跟进与期末评审两级。导师每月末在系统提交《试用期月度评估》，记\n录目标完成情况；试用期最后一周进行期末评审，评审维度包括：目标达成（权重百分之五十）\n、协作与沟通（百分之二十）、学习成长（百分之二十）、价值观（百分之十）。综合得分八十\n分及以上为通过。\n四、提前转正与延长\n综合表现特别优秀（月度评估连续两次九十分以上）且由部门负责人提议的，可申请提前转\n正，提前幅度不超过合同试用期的三分之一。考核不合格的，视情况延长考察（延长后总时长不\n超过法定上限）或依法解除劳动合同；解除决定须由 HRBP 复核证据链完整性。', 305, '2026-08-24 11:36:32');
INSERT INTO `kb_chunk` VALUES (89, '7e1afeb0-8d86-410f-a53f-c3484b5c4c4e', 17, 5, '第五章 导师制', '第五章 导师制\n一、导师资格\n导师由入职满两年、绩效排名前百分之三十的资深员工担任，每个导师同期带教不超过两名\n新人。导师津贴为每月八百元，带教期六个月，新人成功转正且季度绩效达标的导师额外发放一\n次性带教奖金两千元。\n二、导师职责\n入职首周每日与新人进行十五分钟一对一沟通，首月每周至少一次，之后每两周一次；负责\n新人试用期目标制定与事实评价；协助新人融入团队，转正后继续提供三个月的答疑支持。导师\n履职情况纳入其本人绩效的辅导维度。', 135, '2026-08-24 11:36:32');
INSERT INTO `kb_chunk` VALUES (90, '1bed6b43-eea5-4225-989a-62f8a278e8a6', 17, 6, '第六章 培训体系', '第六章 培训体系\n新员工培训体系分为三层：通识层（公司文化、制度、安全合规，入职首周完成）；专业层\n（岗位技能课程与认证，试用期内完成不少于二十四学时）；发展层（转正后按职级选修）。培\n训记录与学时自动计入个人学习档案，作为晋升评审的参考材料之一。', 77, '2026-08-24 11:36:32');
INSERT INTO `kb_chunk` VALUES (91, '0f4438bc-9bbc-4235-87fb-dd4e92018286', 17, 7, '第七章 员工福利概览', '第七章 员工福利概览\n一、法定福利：五险一金按当地上限基数缴纳；二、补充保障：全员商业补充医疗保险（含\n门诊直付、年度体检套餐）；三、假期福利：除法定假期外，公司每年度另设三天全员福利假、\n生日当天半天假；四、生活关怀：免费班车三条线路、加班餐补（二十一点后）、年度旅游基金\n每人一千五百元；五、学习发展：每年每人四千元培训报销额度与内部知识库全部课程免费开放\n。', 113, '2026-08-24 11:36:32');
INSERT INTO `kb_chunk` VALUES (92, '4ec16b54-8c06-4607-aa40-45b58ea77e4a', 17, 8, '第八章 附则', '第八章 附则\n本指引由人力资源部负责解释，自 2026 年 4 月 20\n日起施行。新员工对入职流程的疑问可在入职沟通群@HR助手，工作日两小时内答复。', 47, '2026-08-24 11:36:32');
INSERT INTO `kb_chunk` VALUES (93, '12cce68f-b50f-4bae-a15e-8b6a8968427d', 18, 1, '第一章 文档信息', '产品需求文档：智能客服机器人 PRD\n第一章 文档信息\n文档编号：PROD-PRD-2026-006。版本：V1.9。状态：已评审通过。产品经理：林晓。评审\n日期：2026年5月28日。密级：内部。', 61, '2026-08-24 11:36:59');
INSERT INTO `kb_chunk` VALUES (94, 'd4f6febd-3063-45df-8ed0-3395901d1b90', 18, 2, '第二章 背景与目标', '第二章 背景与目标\n一、业务背景\n客服中心当前日均咨询量 12000 通，其中 61%\n为产品条款、账单、办理流程等重复性问题。人工坐席平均处理时长 4.5 分钟，高峰时段排队超过\n8 分钟，客户满意度跌至 86%。引入智能客服机器人的目标是将重复问题自助解决率提升至 80%\n以上，释放人力承接高价值复杂咨询。\n二、产品目标\n一、上线六个月内机器人独立解决率不低于 75%，十二个月内达到 82%；二、单次应答端到\n端成本不高于人工的十分之一；三、答案必须附带知识库原文引用，引用可点击溯源；四、支持\n数据类问题（如「我上月账单多少」）直查业务系统并回带证据。\n三、成功指标\n北极星指标：机器人独立解决率。辅助指标：转人工率（目标从 39% 降至\n18%）、平均响应时长（目标 3 秒内首响应）、答案引用命中率（目标 95%\n以上）、负面反馈率（目标低于 5%）。', 237, '2026-08-24 11:36:59');
INSERT INTO `kb_chunk` VALUES (95, '24a33cac-b002-4330-8da1-15d83cbbd64a', 18, 3, '第三章 用户角色与场景', '第三章 用户角色与场景\n一、终端咨询用户：通过 App、小程序、网页发起咨询，期望快速获得可信答案；二、客服\n坐席：在机器人无法解决时接续会话，需要完整上下文移交；三、知识库运营员：维护客服知识\n文档，关注文档生效状态；四、运营管理员：配置机器人策略、查看数据看板。', 82, '2026-08-24 11:36:59');
INSERT INTO `kb_chunk` VALUES (96, '7216e8fd-91d8-4dae-9471-80ba22cdcd04', 18, 4, '第四章 功能需求', '第四章 功能需求\n一、多轮对话与意图识别（P0）\n支持连续多轮追问，自动补全指代；对无法识别的意图在两轮澄清后转人工，禁止无限反问\n。意图库初版覆盖 260 个客服意图，覆盖账单查询、套餐变更、故障报修、投诉建议等八大类。\n二、知识库问答与引用溯源（P0）\n答案段落级引用原文，展示文档名、章节与置信度；点击引用弹出原文卡片，卡片内支持查\n看上下五个切片。知识库不存在答案时明确回复「暂未收录」并推送人工入口，禁止编造。\n三、数据直查（P0）\n涉及用户账单、订单、积分的问题，经用户授权后通过 NL2SQL\n通道查询业务库，回复附带数据表格与查询语句；单用户单日数据查询上限 50 次，防刷。\n四、坐席协同（P1）\n机器人应答两次未解决或用户明确要求时，无缝转人工并携带完整对话摘要，坐席接手首响\n不超过 30 秒；支持坐席辅助模式，机器人实时推荐答案供坐席一键发送。\n五、运营看板（P1）\n按天展示会话量、解决率、转人工率、热点未命中问题 Top\n20；未命中问题一键转为知识库补充工单，形成知识运营闭环。\n六、满意度反馈（P2）\n每轮答案展示有帮助与否按钮，负面反馈自动记录会话快照与命中切片，供运营复核并标注\n坏案例。', 317, '2026-08-24 11:36:59');
INSERT INTO `kb_chunk` VALUES (97, '182e3e93-52df-4db2-bab7-c6aada9bb869', 18, 5, '第五章 非功能需求', '第五章 非功能需求\n一、性能：高峰 300 并发会话，首 token 响应 P95 小于 2.5 秒；二、可用性：核心链路 99.9%，\n模型服务降级时自动切换备用模型；三、安全：用户身份脱敏进入模型，日志中手机号打码留存\n；四、审计：全部问答日志保留 180 天，支持按用户与会话导出；五、合规：输出经过敏感词过\n滤，涉及资费承诺的答案必须引用现行有效文档版本。', 113, '2026-08-24 11:36:59');
INSERT INTO `kb_chunk` VALUES (98, 'f6b87edb-078a-4ee4-8cb4-5d286e957443', 18, 6, '第六章 里程碑计划', '第六章 里程碑计划\n2026年7月15日：需求评审冻结；2026年8月30日：P0\n功能联调完成，内部灰度；2026年9月30日：客服中心 10% 流量试点；2026年10月31日：扩量至\n50%，上线 P1 功能；2026年11月30日：全量上线，进入运营优化期。', 82, '2026-08-24 11:36:59');
INSERT INTO `kb_chunk` VALUES (99, 'ffacf851-faac-4cd6-b900-879075e14d77', 18, 7, '第七章 验收标准', '第七章 验收标准\n一、P0 功能验收：内部评测集 500 题通过率 90% 以上，引用命中率 95%\n以上；二、试点验收：试点人群独立解决率不低于 70%，负面反馈率低于 6%，无 P1 级安全事件\n；三、全量验收：达成第二章目标指标且系统连续两周稳定运行，方视为项目交付完成。', 86, '2026-08-24 11:36:59');
INSERT INTO `kb_chunk` VALUES (100, 'efe327d7-58f3-4315-9335-322a6b811cb0', 18, 8, '第八章 风险与依赖', '第八章 风险与依赖\n一、知识文档质量参差：依赖知识运营团队在试点前完成 3000 篇文档清洗；二、业务库访问\n权限：依赖数据团队交付只读账号与表描述；三、模型服务成本：高峰期 token\n成本需财务重新核定预算；四、合规风险：涉及资费表述的答案需法务抽检机制配合。', 82, '2026-08-24 11:36:59');
INSERT INTO `kb_chunk` VALUES (101, '0bef1cd9-f085-476d-864c-9e419c32c107', 19, 1, '一、RAG 技术概述', '检索增强生成技术原理说明\n文档编号：TECH-ARCH-2026-002\n版本：V2.0\n发布日期：2026年6月10日\n密级：内部公开\n一、RAG 技术概述\n1.1 什么是检索增强生成\n检索增强生成（Retrieval-Augmented Generation，RAG）是一种将信息检索与大语言模型生成相结合的技术架构。其核心思想是：在大模型回答用户问题之前，先从外部知识库中检索出与问题相关的文档片段，将检索结果作为上下文注入提示词，让模型基于真实资料作答，从而有效缓解大模型知识过时、私有领域知识缺失与幻觉三类问题。\n1.2 与纯大模型问答的对比\n一、知识时效性：纯大模型的知识截止于训练时间点，RAG 可实时接入增量文档；\n二、私有知识：大模型没有企业内部文档知识，RAG 将私有知识外置为可检索索引；\n三、可溯源性：大模型直接生成的内容无法验证出处，RAG 每个回答都能定位到具体文档切片；\n四、成本控制：相比微调模型，RAG 无需重新训练，更新知识只需重建索引，边际成本低。\n1.3 RAGent 的演进\n传统 RAG 是一条固定流水线：检索 → 拼接 → 生成。', 306, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (102, '86bc1843-0363-4cda-9e67-756aa3d575aa', 19, 2, '一、RAG 技术概述', '1.3 RAGent 的演进\n传统 RAG 是一条固定流水线：检索 → 拼接 → 生成。RAGent（智能体化 RAG）引入决策智能体，由智能体动态决定「是否检索、检索什么、检索几次、是否需要补全、答案是否合格」，将流水线升级为可自我纠正的闭环系统。本系统即为 RAGent 架构的完整实现。', 100, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (103, '5492b640-217d-4086-afe2-37af31d7ad4f', 19, 3, '二、知识入库流水线', '二、知识入库流水线\n2.1 文档解析\n系统支持四种文档格式的解析：', 20, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (104, '64895ac6-191d-4f31-88e2-002a4c4d657a', 19, 4, '一、Markdown（.md）：按 # 标题层级维护路径栈，产出形如「一级标题/二级标题/三级标题」的章节路径；', '一、Markdown（.md）：按 # 标题层级维护路径栈，产出形如「一级标题/二级标题/三级标题」的章节路径；\n二、纯文本（.txt）：按中文章节标题正则（如「第一章」「一、」「1.2.3」）识别层级切分；\n三、PDF（.pdf）：逐页提取文本，页内再按章节正则切分；\n四、Word（.docx）：按段落样式（Heading 样式）与标题正则双通道识别结构。\n2.2 语义切片\n切片（Chunking）是 RAG 效果的关键环节。切片过大导致检索粒度粗糙、噪声多；切片过小导致语义割裂、上下文不足。本系统采用「结构感知切片」策略：\n一、默认参数：目标切片 500 token，相邻切片重叠 50 token；\n二、结构优先：以解析阶段产出的章节块为基本单元，小节合并，大节切分，切片携带完整章节路径；\n三、切片元数据：每个切片记录 doc_id、chunk_uid、chunk_no、section_path、content 与 token_count，全部持久化到 MySQL 与 Elasticsearch。\n2.3 向量化', 288, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (105, 'bc661951-1e20-4df1-92ac-82ea99f31a9d', 19, 5, '一、Markdown（.md）：按 # 标题层级维护路径栈，产出形如「一级标题/二级标题/三级标题」的章节路径；', 'token_count，全部持久化到 MySQL 与 Elasticsearch。\n2.3 向量化\n切片文本通过嵌入模型（默认 text-embedding-v4，输出 1024 维稠密向量）转化为语义向量。批量向量化按每批 10 条并行请求，支持失败重试。向量与原文共同写入 Elasticsearch 的 dense_vector 字段，构建 HNSW 近似最近邻索引（m=16，ef_construction=128）。\n2.4 状态机\n文档入库遵循严格状态机：parsing（解析）→ chunking（切片）→ embedding（向量化）→ ready（就绪）。任一阶段失败进入 failed 状态并记录错误详情，支持从失败点一键重试；重试前自动清理旧切片与旧索引，保证幂等。', 213, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (106, '9e01c8c6-d583-4a07-9550-4a5eeb488535', 19, 6, '三、混合检索与融合', '三、混合检索与融合\n3.1 双路召回\n一、向量检索：将用户问题编码为向量，在 ES 中执行 kNN 搜索，召回语义相近的切片（Top 5）；\n二、关键词检索（BM25）：对问题做分词后执行全文检索，召回字面精确匹配的切片（Top 5），弥补向量检索对专有名词、编号、缩写的不足。\n3.2 RRF 倒数排序融合\n两路结果通过 Reciprocal Rank Fusion 合并。RRF 公式为：score(d) = Σ 1/(K + rank_i(d))，其中 K 取 60，rank_i(d) 为文档 d 在第 i 路检索中的名次。RRF 无需调权、对分数量纲不敏感，是多路检索融合的稳健方案。融合后取 Top 8 进入相关性评估。\n3.3 相关性评估与 CRAG\n评估器对每条候选切片独立打分（1-10 分）：\n一、score ≥ 7：correct，直接作为引用上下文；\n二、5 ≤ score < 7：partial，触发 CRAG（Corrective RAG）流程——剥离无关句、保留核心句，并触发一次查询改写后的补充检索；\n三、score < 5：incorrect，直接丢弃。\n若全部候选为 incorrect，智能体判定「知识库无法回答」，明确告知用户而不是强行编造。', 336, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (107, '416ed94a-d01c-4ff9-8dd6-f0648b580bd7', 19, 7, '四、智能体决策与反思', '四、智能体决策与反思\n4.1 意图识别\n智能体首先对用户输入分类：知识问答 / 数据查询 / 网络搜索 / 闲聊。分类同时完成指代消解，将「它支持哪些格式」补全为「智答支持哪些文档格式」。\n4.2 数据源路由\n按意图选择通路：知识问答路由到混合检索；数据查询路由到 NL2SQL 链路；实时性问题（如「今天」「最新」）路由到网络搜索；闲聊直接生成。多条通路可组合，例如「对比我们产品与竞品最新售价」同时触发知识库检索与网络搜索。\n4.3 反思重答\n答案生成后进入自检：是否引用了检索内容？是否完整回答了问题？是否包含矛盾表述？自检不通过则触发反思，智能体重新规划检索词或调整回答结构，最多重试 2 轮，仍不通过则以最佳候选答案输出并附带低置信提示。\n4.4 决策日志\n六个决策点（意图识别、数据源选择、检索评估、知识补全、反思重答、引用组装）的输入、输出、耗时与置信度全量落库，前端以流程图与时间线形式可视化，便于调试与效果归因。', 257, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (108, '8749cbea-ed15-4f44-a8f9-403763b30894', 19, 8, '五、NL2SQL 数据问答', '五、NL2SQL 数据问答\n5.1 生成与校验\n智能体依据预先注入的表结构 Schema（表名、字段、枚举值、样例数据）生成 SQL。执行前经过三层校验：\n一、语法校验：SQL 解析器语法检查；\n二、安全校验：白名单只允许 SELECT，正则黑名单拦截 DROP / DELETE / UPDATE / INSERT / TRUNCATE / ALTER；\n三、成本校验：EXPLAIN 预估扫描行数，超过 100 万行的查询强制加 LIMIT 或拒绝执行。\n5.2 证据链\n数据问答回答附带三重证据：生成的 SQL 语句、执行结果表格（最多展示 50 行）、命中字段的数据来源说明，用户可点击验证每个数字的来源。', 190, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (109, 'dce8e91c-d10e-4ca0-a349-28a29e243734', 19, 9, '六、工程性能优化', '六、工程性能优化\n一、流式输出：回答全程 SSE 流式推送，决策事件、检索过程、正文逐段到达前端，首字节时间低于 2.5 秒；\n二、超时熔断：单轮问答总超时 120 秒，检索、生成子阶段分级超时；\n三、历史压缩：多轮对话保留最近 8 轮上下文，超出部分摘要压缩；\n四、缓存策略：相同问题的检索结果按 embedding 相似度缓存，命中阈值 0.98，缓存命中时检索耗时降至 50 毫秒以内。', 122, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (110, '59f2e27b-e45c-4d08-bae3-82272dd87188', 19, 10, '七、评测体系', '七、评测体系\n7.1 评测指标\n一、检索质量：Recall@5、MRR（平均倒数排名）、NDCG@10；\n二、生成质量：答案准确率（人工标注）、引用命中率（引用是否真实支撑答案）、幻觉率；\n三、系统性能：检索 P95 延迟、端到端 P95 延迟、吞吐量 QPS。\n7.2 评测集建设\n内部标准评测集覆盖 1200 个问题，按问题类型分为事实型（40%）、对比型（20%）、计算型（15%）、列表型（15%）、否定型（10%，考察「知识库没有时承认不知道」）。每次版本迭代全量回归，指标劣化超过 1 个百分点阻塞发布。', 160, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (111, '1a666869-014e-4275-ab8a-5de61687bda4', 19, 11, '八、参考实现组件', '八、参考实现组件\n一、后端框架：FastAPI + uvicorn，SSE 由 sse-starlette 提供；\n二、编排与模型接入：LangChain 风格的链式编排，OpenAI 兼容协议接入 DeepSeek 与百炼嵌入；', 71, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (112, '52edd3a4-41a8-4b2f-b275-299d795e455e', 19, 12, '三、存储：MySQL 8.x（业务元数据）+ Elasticsearch 8.x/9.x（全文、向量与日志）；', '三、存储：MySQL 8.x（业务元数据）+ Elasticsearch 8.x/9.x（全文、向量与日志）；\n四、前端：Vue 3 + TypeScript + Vite，流程可视化基于 SSE 决策事件流驱动。', 66, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (113, 'b97daa05-8546-4083-a2d1-41a431ac35d1', 20, 1, '一、设计原则', '前端界面设计与交互规范\n一、设计原则\n本规范适用于公司全部 B 端与 C 端产品界面。四条核心原则：一、一致性：同一概念在全产品使用同一术语与组件，禁止同义异形；二、效率优先：高频操作路径不超过三步，常用入口固定可见；三、信息降噪：单屏主色调区域不超过三处，次要操作默认收起；四、可恢复：任何破坏性操作提供撤销或二次确认。', 100, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (114, '8ab897fb-4b4f-443a-aa31-f518a42aa934', 20, 2, '二、色彩体系', '二、色彩体系\n2.1 品牌色板\n主色为品牌蓝 #1E66F5，用于主按钮、链接与选中态；辅助色包括成功绿 #16A34A、警告橙 #EA8A00、错误红 #DC2626、信息蓝 #0284C7。中性色阶从 #0F172A（标题）到 #F8FAFC（页面背景）共十级。深浅两套主题共用同一色相，仅明度映射不同。\n2.2 使用规则\n主按钮同一视图只出现一个；错误红仅用于校验失败与危险操作，禁止用于装饰；文本对比度不低于 4.5:1（大字号不低于 3:1）；数据可视化色板为十二色序列，分类色顺序不可随意调整，保证跨页面图表颜色语义一致。', 166, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (115, 'b908c312-8230-4c18-9cb0-3d603929f682', 20, 3, '三、排版与间距', '三、排版与间距\n栅格：桌面端 12 栏，内容区最大宽度 1440px，左右留白 24px；间距体系为 4 的倍数（4/8/12/16/24/32/48），禁止出现 10、15 等非体系间距。字号体系：页面标题 20px、卡片标题 16px、正文 14px、辅助文字 12px、最小字号不低于 12px。行高正文 1.6、标题 1.3。中文字体优先级：PingFang SC、Microsoft YaHei、系统默认无衬线。', 131, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (116, 'df01b73c-d87e-41e3-a79b-bc479e0cdd1c', 20, 4, '四、组件规范', '四、组件规范\n4.1 按钮与表单\n按钮高度统一 36px（紧凑场景 28px），圆角 6px；按钮状态必须包含默认、悬停、按下、加载、禁用五态。表单标签统一右对齐置于输入框上方；必填项用星号标注于标签左；校验错误显示在字段下方并同步红色描边；提交后服务端校验失败的滚动定位到第一个错误字段。\n4.2 反馈与加载\n操作反馈三类：轻提示（Toast，两秒自动消失，不打断操作）、抽屉与弹窗（需要用户处理的事项，弹窗宽度统一 480px 或 720px 两档）、页面级结果页（任务完成或失败的终态）。接口耗时超过 800 毫秒必须出现加载态；超过 5 秒需提供进度或骨架屏。列表页加载失败保留已加载数据并顶部提示重试。\n4.3 数据表格\n表格默认展示 6 至 8 列，其余收进列设置；行高 48px，密度模式可切换至 36px；长文本两行截断并悬停浮层展示全文；批量操作按钮在选择行数大于零时出现在表格左上角。分页默认每页 20 条，可选 10/20/50/100。', 267, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (117, 'a974067f-605f-48f6-a7ea-7cb55321f1f7', 20, 5, '五、交互反馈与动效', '五、交互反馈与动效\n动效时长：微交互 120 至 200 毫秒，页面切换不超过 300 毫秒，超出视为卡顿。动效曲线统一使用 ease-out，禁止弹跳类曲线。用户主动触发展开收起时使用高度过渡；禁止在数据加载完成前使用空白闪跳。尊重系统「减少动态效果」设置，检测到该偏好时关闭非必要动效。', 90, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (118, '4bdb38e4-ae8f-4df3-96f7-64ca3245d0ce', 20, 6, '六、无障碍与国际化', '六、无障碍与国际化\n全部可交互元素可键盘触达，焦点可见；图标按钮必须提供 aria-label；表单错误同时使用颜色与文字提示，不单靠颜色传达状态；中文界面文案禁止中英混排的空格不一致问题（统一使用全角标点）。国际化预留文案外扩 30% 的空间余量，禁止绝对定位拼接文案。', 84, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (119, '6c728695-8f4b-40ae-ba27-06c51595d62f', 20, 7, '七、响应式断点', '七、响应式断点\n断点定义：移动端小于 768px、平板 768 至 1024px、桌面大于 1024px。移动端导航收起为底部标签栏，表格降级为卡片列表，复杂筛选器收进浮层。对话类页面在移动端固定输入框于软键盘之上。', 67, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (120, 'bdb23bb9-5ed7-4e56-bd42-829c58e09033', 20, 8, '八、附则', '八、附则\n本规范维护于设计资产库，版本 V2.4，更新日期 2026 年 5 月 28 日。新组件入库须附交互说明与多状态截图，由设计评审会通过后发布。', 47, '2026-08-24 11:37:01');
INSERT INTO `kb_chunk` VALUES (121, 'b0127544-fe55-4a52-b394-c141494e316c', 21, 1, '数据源接入配置指南/一、支持的 数据源类型', '数据源接入配置指南\n> 文档编号：TECH-CONF-2026-004 ｜ 版本：V1.5 ｜ 更新日期：2026-05-30 ｜ 适用角色：系统管理员、实施工程师\n一、支持的 数据源类型\n系统当前支持两类外部数据源接入，用于 NL2SQL 数据问答：\n| 类型 | 标识 | 典型用途 | 网络要求 |\n| --- | --- | --- | --- |\n| MySQL | `mysql` | 业务数据表查询（订单、销售、库存） | 后端服务可访问目标库 3306 端口 |\n| HTTP API | `http_api` | 已有接口数据聚合查询 | 后端服务可访问目标 API 域名 |\n接入原则：仅接入「查询型」数据；生产库建议通过只读副本或只读账号接入；单知识库最多绑定 3 个数据源。', 216, '2026-08-24 11:37:02');
INSERT INTO `kb_chunk` VALUES (122, '308df561-0153-457c-b831-6327458180be', 21, 2, '数据源接入配置指南/二、MySQL 数据源接入', '二、MySQL 数据源接入\n2.1 前置检查清单\n1. 目标 MySQL 版本为 5.7 或 8.x，字符集建议 utf8mb4；\n2. 创建专用只读账号，仅授予目标库的 `SELECT` 权限：\n```sql\nCREATE USER \'rag_reader\'@\'%\' IDENTIFIED BY \'强密码\';\nGRANT SELECT ON sales_db.* TO \'rag_reader\'@\'%\';\nFLUSH PRIVILEGES;\n```\n3. 确认后端服务器到目标库的网络连通：`mysql -h <host> -P 3306 -u rag_reader -p --default-character-set=utf8mb4`；\n4. 确认待查询表已建索引，大表（超过 500 万行）建议预先建立汇总表。\n2.2 页面配置步骤\n进入「数据源管理」→「新增数据源」，填写以下字段：\n| 字段 | 必填 | 说明 |\n| --- | --- | --- |\n| 名称 | 是 | 全局唯一，建议「业务-库-环境」格式，如 sales-mysql-prod |', 300, '2026-08-24 11:37:02');
INSERT INTO `kb_chunk` VALUES (123, '5f96e679-0b73-4472-afa7-637466d2fa19', 21, 3, '数据源接入配置指南/二、MySQL 数据源接入', '名称 | 是 | 全局唯一，建议「业务-库-环境」格式，如 sales-mysql-prod |\n| 类型 | 是 | 选择 MySQL |\n| 主机 | 是 | IP 或域名 |\n| 端口 | 是 | 默认 3306 |\n| 数据库名 | 是 | 目标库名 |\n| 用户名 | 是 | 只读账号 |\n| 密码 | 是 | 保存后加密存储，页面不再回显 |\n| 描述 | 否 | 数据内容说明，会注入大模型上下文帮助生成 SQL |\n保存后点击「测试连通」，成功标准：连接耗时 2 秒内且无错误返回。\n2.3 表结构同步与筛选\n连通成功后系统自动抓取表结构（表名、字段、类型、注释）。配置建议：\n1. 仅勾选允许查询的表，敏感表（如用户明文信息表）一律不勾选；\n2. 为每张表补充中文业务描述（一句话即可），描述质量直接影响 SQL 生成准确率；\n3. 枚举字段（如 status）在备注中列出取值含义，例如 `status: 1=待支付 2=已支付 3=已退款`；\n4. 表结构变更后（加列、改注释）需点击「重新同步」刷新 Schema。\n2.4 性能与安全约束', 299, '2026-08-24 11:37:02');
INSERT INTO `kb_chunk` VALUES (124, '10822cde-78f4-4acf-a038-656762097714', 21, 4, '数据源接入配置指南/二、MySQL 数据源接入', '4. 表结构变更后（加列、改注释）需点击「重新同步」刷新 Schema。\n2.4 性能与安全约束\n- 生成 SQL 强制只读校验，`SELECT` 之外的语句直接拒绝；\n- 查询超时 10 秒，超时自动终止并提示用户缩小时间范围；\n- 预估扫描行数超过 100 万行时，系统自动追加 LIMIT 或拒绝执行；\n- 单次返回最多 50 行明细，聚合查询不受此限制。', 112, '2026-08-24 11:37:02');
INSERT INTO `kb_chunk` VALUES (125, '84ee7663-6374-4ae4-95b1-22e8e5392062', 21, 5, '数据源接入配置指南/三、HTTP API 数据源接入', '三、HTTP API 数据源接入\n3.1 适配要求\n目标 API 须满足：\n1. 支持 GET 请求，返回 JSON；\n2. 响应时间 P95 不超过 3 秒；\n3. 返回结构稳定，数组数据位于固定路径（如 `data.items`）。\n3.2 配置字段\n| 字段 | 说明 |\n| --- | --- |\n| 请求地址 | 完整 URL，支持查询参数占位符，如 `/api/v1/orders?status={status}` |\n| 请求头 | 支持 Authorization 等自定义头，Token 加密存储 |\n| 响应数据路径 | 数组所在 JSON 路径，如 `data.items` |\n| 参数说明 | 每个占位参数的类型与取值说明，供大模型填写 |\n3.3 示例：接入订单查询接口\n请求地址：`https://crm.example.com/api/v1/orders?region={region}&month={month}`\n参数说明：\n- region：大区编码，取值 east / north / south / west；\n- month：月份，格式 YYYY-MM。\n响应数据路径：`data.items`。配置完成后在测试窗格输入示例参数验证返回结构。', 337, '2026-08-24 11:37:02');
INSERT INTO `kb_chunk` VALUES (126, '9ad5be1e-8cc8-44bf-83be-957588ec38ba', 21, 6, '数据源接入配置指南/四、数据源与知识库绑定', '四、数据源与知识库绑定\n数据源配置完成后，需绑定到具体知识库才会生效：\n1. 进入「知识库设置」→「数据源绑定」；\n2. 从已测通的数据源列表中勾选（最多 3 个）；\n3. 绑定后该知识库的对话中，智能体可将数据类问题路由到对应数据源；\n4. 解绑立即生效，进行中的查询不受影响，新对话不再路由。', 92, '2026-08-24 11:37:02');
INSERT INTO `kb_chunk` VALUES (127, 'bece5a71-2358-465f-bfd7-496769199378', 21, 7, '数据源接入配置指南/五、常见问题排查', '五、常见问题排查\n5.1 连通测试失败\n| 现象 | 可能原因 | 处理方式 |\n| --- | --- | --- |\n| Connection refused | 目标库未放行后端 IP | 在目标库安全组放行后端出口 IP |\n| Access denied | 账号密码错误或权限不足 | 核对账号，确认 SELECT 权限已授予 |\n| 连接超时 | 网络不通 / 端口错误 | 检查 VPC 路由、安全组与端口 |\n| 字符乱码 | 字符集不一致 | 连接串强制 utf8mb4 |\n5.2 查询结果不对\n1. 检查表业务描述是否准确（描述误导会导致错误关联）；\n2. 枚举值含义缺失时补全备注并重新同步 Schema；\n3. 在「检索测试」页面直接粘贴生成的 SQL 在目标库手动执行比对；\n4. 查看决策日志中 datasource 决策点，确认路由到了预期的数据源。\n5.3 查询很慢\n1. 确认过滤字段是否有索引（尤其时间字段）；\n2. 缩小查询时间范围，建议按月分批查询；\n3. 大表预先构建日/月粒度汇总表，将汇总表接入而非明细表。', 296, '2026-08-24 11:37:02');
INSERT INTO `kb_chunk` VALUES (128, '5f835b21-2cb2-4e98-84ed-2ad5e45bc34e', 21, 8, '数据源接入配置指南/六、变更记录', '六、变更记录\n- V1.5（2026-05-30）：新增 HTTP API 数据源类型；表结构支持手动重新同步。\n- V1.2（2026-04-11）：新增扫描行数预估校验与自动 LIMIT。\n- V1.0（2026-03-20）：首个版本，支持 MySQL 数据源接入。', 84, '2026-08-24 11:37:02');
INSERT INTO `kb_chunk` VALUES (129, '60ea6310-a311-4aba-ab44-001bb1b3e5bd', 22, 1, '系统API接口文档 V2/一、接口约定', '系统API接口文档 V2\n> 文档编号：TECH-API-2026-003 ｜ 版本：V2.1 ｜ 更新日期：2026-06-18 ｜ 基础路径：`/api`\n一、接口约定\n1.1 基础说明\n- **协议**：HTTP/1.1 与 HTTP/2，全链路强制 HTTPS；\n- **数据格式**：请求与响应均为 UTF-8 编码的 JSON（文件上传除外），时间字段统一为 ISO 8601 格式（如 `2026-06-18T09:30:00+08:00`）；\n- **鉴权方式**：所有管理接口需在请求头携带 `Authorization: Bearer <API_KEY>`；对话接口支持 API Key 与临时会话 Token 两种方式；\n- **分页约定**：列表接口统一使用 `page`（从 1 开始）与 `page_size` 参数，响应包含 `items / total / page / page_size` 四个字段。\n1.2 通用错误结构\n```json\n{\n\"detail\": \"知识库名称「产品文档」已存在（name 唯一约束）\"\n}\n```', 299, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (130, '0eceb446-4061-4215-823c-8556ca4f5735', 22, 2, '系统API接口文档 V2/一、接口约定', 'son\n{\n\"detail\": \"知识库名称「产品文档」已存在（name 唯一约束）\"\n}\n```\n| HTTP 状态码 | 含义 | 处理建议 |\n| --- | --- | --- |\n| 400 | 参数错误或业务规则校验失败 | 检查请求体字段 |\n| 401 | 未携带或 API Key 无效 | 刷新凭证 |\n| 404 | 资源不存在 | 检查路径中的 ID |\n| 409 | 资源冲突（重名等） | 更换名称后重试 |\n| 429 | 触发限流（默认 60 次/分钟） | 指数退避重试 |\n| 500 | 服务端内部错误 | 联系管理员并附 trace_id |', 181, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (131, 'a8a9ca65-3e4b-40a1-b9e5-41a9a1b9dcf6', 22, 3, '系统API接口文档 V2/二、知识库管理', '二、知识库管理\n2.1 创建知识库\n`POST /api/admin/kb`\n请求体：\n```json\n{\n\"name\": \"产品文档库\",\n\"description\": \"存放产品白皮书、需求文档与发布说明\"\n}\n```\n响应 `201`：\n```json\n{\n\"id\": 3,\n\"name\": \"产品文档库\",\n\"description\": \"存放产品白皮书、需求文档与发布说明\",\n\"doc_count\": 0,\n\"chunk_count\": 0\n}\n```\n规则说明：`name` 必填且全局唯一（违反返回 409）；`description` 可选，不超过 200 字。\n2.2 查询知识库列表\n`GET /api/admin/kb`\n响应为知识库数组，每个元素额外包含 `doc_count`（ready 状态文档数）与 `chunk_count`（切片总数）。\n2.3 上传文档\n`POST /api/admin/kb/{kb_id}/documents`\n请求为 `multipart/form-data`，字段名 `file`。', 293, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (132, '1d7f378f-2b24-475c-ba8d-06038841d963', 22, 4, '系统API接口文档 V2/二、知识库管理', '}/documents`\n请求为 `multipart/form-data`，字段名 `file`。支持 md / txt / pdf / docx，单文件不超过 20MB。响应 `202` 返回文档记录，入库流水线异步执行，前端应轮询文档状态直至 `ready` 或 `failed`：\n| status | 含义 |\n| --- | --- |\n| parsing | 正在解析 |\n| chunking | 正在切片 |\n| embedding | 正在向量化 |\n| ready | 入库完成，chunk_count 可用 |\n| failed | 失败，查看 error_msg |\n2.4 文档切片明细\n`GET /api/admin/kb/{kb_id}/documents/{doc_id}/chunks?page=1&page_size=8`\n返回该文档的切片列表（chunk_no、section_path、content、token_count），`page_size` 上限 50。仅 `ready` 状态文档可查询。\n2.5 失败重试与删除', 299, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (133, '20b736d8-dd44-4932-b90a-67a6191d5156', 22, 5, '系统API接口文档 V2/二、知识库管理', '，`page_size` 上限 50。仅 `ready` 状态文档可查询。\n2.5 失败重试与删除\n- 重试：`POST /api/admin/kb/{kb_id}/documents/{doc_id}/retry`，仅 `failed` 状态可调用，返回 202；\n- 删除：`DELETE /api/admin/kb/{kb_id}/documents/{doc_id}`，先清理 ES 索引再删除 MySQL 记录，操作不可恢复。', 135, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (134, 'b1b3b41d-2f7f-4e71-9847-b4873e20646f', 22, 6, '系统API接口文档 V2/三、对话问答', '三、对话问答\n3.1 发起对话（SSE 流式）\n`POST /api/chat`\n请求体：\n```json\n{\n\"kb_id\": 3,\n\"question\": \"系统支持哪些文档格式？\",\n\"history_id\": \"conv_9f2a8c\",\n\"mode\": \"agentic\"\n}\n```\n| 字段 | 类型 | 必填 | 说明 |\n| --- | --- | --- | --- |\n| kb_id | int | 是 | 目标知识库 ID |\n| question | string | 是 | 用户问题，上限 2000 字符 |\n| history_id | string | 否 | 会话 ID，首次对话不传，服务端在首个事件返回 |\n| mode | string | 否 | `agentic`（默认，六决策点全开）或 `fast`（跳过反思与补全） |\n响应为 `text/event-stream`，事件按顺序推送：\n1. `meta`：会话 ID、使用的模型与知识库信息；', 278, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (135, 'd4a3ca76-d3b4-43fc-a749-28b9ad037bb8', 22, 7, '系统API接口文档 V2/三、对话问答', 'ent-stream`，事件按顺序推送：\n1. `meta`：会话 ID、使用的模型与知识库信息；\n2. `decision`：六个决策点事件，`type` 取值 `intent / datasource / grading / crag / reflect / citation`，每个事件携带决策结论、置信度与耗时毫秒数；\n3. `retrieval`：检索命中的引用列表（doc_name、chunk_no、score、摘要前 100 字）；\n4. `token`：正文增量片段，逐段推送；\n5. `done`：统计信息（总耗时、token 消耗、引用数）；\n6. `error`：错误事件（流中途失败时推送，随后关闭连接）。\n3.2 引用溯源\n`GET /api/admin/chunks/by-citation?doc_name=产品白皮书&chunk_no=5`\n返回引用命中的文档记录与切片原文。`doc_name` 为文档名去掉扩展名；若同名文档多次入库，返回最新一条 ready 记录。\n3.3 决策日志查询\n`GET /api/admin/decision-logs?history_id=conv_9f2a8c`\n返回该会话全部决策点日志，用于调试与效果分析。日志默认保留 90 天，可在管理端配置。', 348, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (136, 'f867e1c3-5045-4a9f-8684-12a1ef8277f2', 22, 8, '系统API接口文档 V2/四、数据源与 NL2SQL', '四、数据源与 NL2SQL\n4.1 数据源管理\n- 新增：`POST /api/admin/datasources`，body 包含 `name / type(mysql|http_api) / config / description`，其中 MySQL 数据源需提供 host、port、user、password、database，密码加密存储；\n- 测试连通：`POST /api/admin/datasources/{id}/test`，返回连通耗时与错误详情（如有）；\n- 删除：`DELETE /api/admin/datasources/{id}`，已被知识库绑定的数据源不可删除（返回 409）。\n4.2 数据问答安全规则\n生成的 SQL 必须通过只读校验：仅允许 `SELECT` 语句；禁止多语句；执行超时 10 秒；结果集超过 50 行自动截断并在响应中标注 `truncated: true`。', 254, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (137, 'a4746e49-3826-4588-beee-47d837d5739c', 22, 9, '系统API接口文档 V2/五、检索测试', '五、检索测试\n`POST /api/admin/retrieval-test`\n```json\n{\n\"kb_id\": 3,\n\"query\": \"年假有几天\",\n\"top_k\": 5,\n\"retrievers\": [\"vector\", \"bm25\", \"fused\"]\n}\n```\n返回三路召回结果与各自得分，用于评估检索质量。`retrievers` 可传空数组，默认全部执行。', 117, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (138, '556e0a43-1e6e-42ba-903c-2b812e7341ee', 22, 10, '系统API接口文档 V2/六、速率限制与配额', '六、速率限制与配额\n- 对话接口：每 API Key 60 次/分钟，并发流式连接上限 10；\n- 文档上传：每知识库每分钟 30 个文件；\n- 嵌入接口：批量向量化每分钟 600 条切片；\n- 超限返回 429，响应头包含 `Retry-After` 秒数。', 81, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (139, '53f5b0e2-cb9b-433c-8961-77ea249478aa', 22, 11, '系统API接口文档 V2/七、变更记录', '七、变更记录\n- V2.1（2026-06-18）：新增引用溯源接口；决策日志支持按会话查询。\n- V2.0（2026-05-06）：对话接口全面切换 SSE；新增 `fast` 模式。\n- V1.3（2026-03-02）：新增检索测试接口与决策点可视化事件。', 81, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (140, '52d96b86-40f7-4460-b4dd-22cbc09ab237', 23, 1, '一、产品概述', '智能问答机器人产品白皮书\n文档编号：PROD-WP-2026-001\n版本：V3.2\n发布日期：2026年5月20日\n密级：对外公开\n一、产品概述\n1.1 产品定位\n「智答」（SmartAnswer）是一款面向企业级客户的知识增强型智能问答机器人。产品以检索增强生成（RAG）技术为核心架构，帮助企业将散落在文档、工单、数据库中的私有知识转化为可对话、可溯源的智能问答服务，广泛应用于智能客服、内部知识助手、IT 运维助手等场景。\n1.2 核心价值主张\n一、知识资产激活：支持 PDF、Word、Markdown、纯文本等多种格式的知识入库，平均 10 分钟完成一个中等规模知识库的搭建。\n二、答案可信可溯源：每个回答均附带原文引用出处（文档名、章节、切片编号），点击引用可定位原文上下文，杜绝大模型的幻觉风险。\n三、多源融合决策：融合向量检索、关键词检索、结构化数据查询（NL2SQL）与网络搜索四条通路，由智能体（Agent）自动编排，复杂问题自动拆解为多步任务。\n四、私有化部署：支持全私有化部署，模型推理、向量索引与业务数据全部保留在客户内网，满足金融、政务等行业的合规要求。', 305, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (141, 'b7439967-3c21-48b6-92a1-92704981147d', 23, 2, '一、产品概述', '支持全私有化部署，模型推理、向量索引与业务数据全部保留在客户内网，满足金融、政务等行业的合规要求。\n1.3 目标客户\n一、中大型企业客服中心：需要 7×24 小时自助应答，降低人工坐席成本；\n二、IT 与运维团队：沉淀运维手册，缩短故障定位时间；\n三、知识密集型团队：法务、咨询、研究院所等需要快速检索海量文档；\n四、软件厂商：通过开放 API 将问答能力嵌入自有产品。', 115, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (142, '02833c3d-459b-43bc-97af-3a975faa0b88', 23, 3, '二、产品能力全景', '二、产品能力全景\n2.1 知识库管理\n支持创建多个独立知识库，实现知识隔离。知识库管理能力包括：', 30, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (143, '2e53705f-5135-47cd-81df-bc6af365f852', 23, 4, '一、文档上传：单文件上限 20MB，支持 md / txt / pdf / docx 四种格式，批量上传自动排队处理；', '一、文档上传：单文件上限 20MB，支持 md / txt / pdf / docx 四种格式，批量上传自动排队处理；\n二、智能切片：按标题层级语义切片，默认切片 500 token、重叠 50 token，切片过程保留章节路径信息；\n三、状态机管理：文档入库经历 parsing → chunking → embedding → ready 四个状态，失败可一键重试，错误信息透明可查；\n四、切片级溯源：支持查看任意文档的切片明细，包含切片编号、章节路径、内容与 token 数。\n2.2 智能检索\n一、混合检索：BM25 关键词检索与稠密向量检索并行执行，通过 RRF（倒数排序融合，K=60）合并排序；\n二、相关性评估：检索结果逐条打分（1-10 分），7 分以上判定为高度相关直接引用，5-7 分为部分相关触发知识补全（CRAG），5 分以下丢弃；\n三、查询改写：对话上下文自动补全指代（如「它的价格呢」自动改写为完整问题），多轮对话准确率提升 23%；\n四、意图路由：智能体自动识别问题意图，闲聊类直答，知识类走检索，数据类走 NL2SQL，实时类走网络搜索。\n2.3 智能体编排\n系统内置六个关键决策点，全部决策过程可视化：\n一、意图识别：判断问题类型与是否需要检索；', 335, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (144, 'da8a86f7-00dd-4cf5-ae9b-2c5441bfb70c', 23, 5, '二、数据源选择：决定调用哪些检索通路（向量库 / ES / 数据库 / 网络搜索）；', '二、数据源选择：决定调用哪些检索通路（向量库 / ES / 数据库 / 网络搜索）；\n三、检索评估：对召回内容进行相关性分级；\n四、知识补全：检索质量不足时触发改写重查，最多重试 2 轮；\n五、反思重答：生成答案自检不通过时重新组织，最多 2 轮；\n六、引用组装：将命中切片装配为可点击的引用列表。\n2.4 数据问答（NL2SQL）\n用户以自然语言提问，系统自动生成 SQL 并在授权数据源上执行，返回数据表格与图表。执行前经过 SQL 安全校验（禁止 DROP / DELETE / UPDATE / INSERT），仅放行只读查询。回答附带生成的 SQL 语句与执行结果证据视图，全程可审计。', 185, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (145, '067b2333-d22a-40dc-a885-f521a231c548', 23, 6, '三、性能与规格指标', '三、性能与规格指标\n3.1 性能基准（单节点，8C32G，100 万切片规模）\n一、检索延迟：混合检索 P95 ≤ 800 毫秒；\n二、端到端延迟：首 token 输出 P95 ≤ 2.5 秒，完整回答平均 8-15 秒（流式输出）；\n三、并发能力：单节点支持 50 路并发会话，水平扩展线性提升；\n四、检索准确率：在内部评测集（1200 个问题）上 Recall@5 达到 91.4%，端到端答案准确率 87.2%。\n3.2 部署规格\n一、最低配置：8 核 CPU、32GB 内存、500GB SSD，可支持 10 万切片；\n二、推荐配置：16 核 CPU、64GB 内存、1TB SSD，可支持 100 万切片；', 191, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (146, '582fc36a-8db7-401e-97cc-0030460dcc12', 23, 7, '三、依赖组件：MySQL 8.x（元数据）、Elasticsearch 8.x/9.x（全文与向量）、向量嵌入服务；', '三、依赖组件：MySQL 8.x（元数据）、Elasticsearch 8.x/9.x（全文与向量）、向量嵌入服务；\n四、模型支持：默认接入 DeepSeek 系列（OpenAI 兼容协议），可替换为任意兼容模型；嵌入模型默认使用 text-embedding-v4（1024 维）。', 88, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (147, '61ad0c3b-57bc-4334-8473-f0c1b4af3098', 23, 8, '四、典型应用场景', '四、典型应用场景\n4.1 智能客服\n某股份制银行信用卡中心接入后，知识库入库产品条款、常见问题 3200 篇。上线三个月，机器人独立解决率从 61% 提升至 82%，平均人工转接等待时长下降 40%，客户满意度稳定在 94% 以上。\n4.2 IT 运维助手\n某互联网公司运维团队将 1500 篇运维手册、历史故障工单导入知识库。值班工程师通过对话即可查询处置预案，故障平均定位时间（MTTI）从 25 分钟缩短至 9 分钟，新员工上手周期从三个月缩短至三周。\n4.3 内部制度问答\n某 3000 人规模制造企业将人事、财务、行政制度共 860 份文件入库，员工咨询类 HR 工单量下降 57%，制度类问题的答复一致性显著提升。', 194, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (148, '04844a25-1259-43d7-8afb-6aa1274cb635', 23, 9, '五、安全与合规', '五、安全与合规\n一、数据隔离：多知识库物理隔离，检索默认不跨库，跨库检索需显式授权；\n二、传输加密：全链路 HTTPS，模型调用通道支持 TLS 1.3；\n三、权限审计：所有问答、检索、入库操作全量留痕，支持按用户、时间、知识库维度导出审计报表；\n四、内容安全：输出内容经过敏感词过滤与安全护栏，可配置禁答主题清单。', 98, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (149, '05f03b10-6b98-4c9e-8b69-38c1384dd3c3', 23, 10, '六、版本路线', '六、版本路线\n2026 Q2：上线多模态问答（图片理解）、答案评价反馈闭环；\n2026 Q3：上线知识库自动更新（定时同步企业网盘）、对话式数据可视化；\n2026 Q4：上线多智能体协作（检索、计算、写作三个专家智能体协同）；\n2027 H1：上线领域微调能力，支持客户自有语料的轻量化模型定制。', 92, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (150, '987117ae-9107-4fb6-a866-12afa18bec48', 23, 11, '七、联系方式', '七、联系方式\n产品官网：www.smartanswer.example.com\n商务咨询：sales@smartanswer.example.com\n技术支持：support@smartanswer.example.com\n服务热线：400-800-1234（工作日 9:00-18:00）', 90, '2026-08-24 11:37:03');
INSERT INTO `kb_chunk` VALUES (151, '99d799bf-f263-4235-8bfb-df161dec69f4', 24, 1, '一、备份策略总览', '数据库备份与恢复操作指南\n文档编号：OPS-DBA-2026-002\n版本：V3.0\n发布日期：2026年3月25日\n适用范围：MySQL 8.x 生产与预发布集群、Elasticsearch 数据集群\n一、备份策略总览', 68, '2026-08-24 11:37:27');
INSERT INTO `kb_chunk` VALUES (152, 'd9966ff6-fcee-4ce3-8bd8-fb597b5e1393', 24, 2, '1.1 备份对象与 RPO/RTO 目标', '1.1 备份对象与 RPO/RTO 目标\n一、核心交易库（trade_db）：RPO 不超过 5 分钟（binlog 实时归档），RTO 不超过 60 分钟；', 49, '2026-08-24 11:37:27');
INSERT INTO `kb_chunk` VALUES (153, '67d9453a-f78d-4199-bad3-f9d2469e3dde', 24, 3, '二、业务主库（crm_db / sales_db）：RPO 不超过 15 分钟，RTO 不超过 2 小时；', '二、业务主库（crm_db / sales_db）：RPO 不超过 15 分钟，RTO 不超过 2 小时；\n三、日志与统计库（log_db）：RPO 24 小时，RTO 8 小时，允许丢失当天数据；\n四、Elasticsearch 索引：知识库索引重建即可恢复，不纳入磁带备份；决策日志索引每日快照至冷节点。\n1.2 备份方式与周期\n一、全量备份：每日 02:00 通过 XtraBackup 物理备份，保留最近 14 天；', 131, '2026-08-24 11:37:27');
INSERT INTO `kb_chunk` VALUES (154, '5b2f5e43-306d-428b-9c40-be0035e21d17', 24, 4, '二、增量备份：每日 08:00 / 14:00 / 20:00 三次，基于全量的增量，保留 7 天；', '二、增量备份：每日 08:00 / 14:00 / 20:00 三次，基于全量的增量，保留 7 天；\n三、binlog 归档：实时同步至备份机，保留 30 天，用于任意时间点恢复（PITR）；\n四、月度归档：每月 1 日将上月全量备份归档至异地对象存储，保留 12 个月；\n五、备份存储容量规划：主备份机 40TB，异地存储按每月 8TB 增长预估。\n1.3 备份成功率要求\n全量备份月度成功率必须达到 100%，单次失败视为 P3 事件，值班 DBA 当日完成重跑并在交接班记录中说明原因。连续两次失败升级为 P2 事件并通报运维经理。', 167, '2026-08-24 11:37:27');
INSERT INTO `kb_chunk` VALUES (155, 'e0f9c57e-1839-4697-961d-da20ab99b828', 24, 5, '二、MySQL 备份操作规范', '二、MySQL 备份操作规范\n2.1 全量备份执行流程\n一、备份脚本每日 02:00 由调度系统触发，先对备份库执行 FLUSH TABLES WITH READ LOCK 短暂加锁获取一致性位点，随后释放；', 64, '2026-08-24 11:37:27');
INSERT INTO `kb_chunk` VALUES (156, '2d30d388-99a4-4922-9f3d-2fd57af22f9d', 24, 6, '二、XtraBackup 并行 4 线程拷贝数据文件至 /backup/full/{日期}/ 目录；', '二、XtraBackup 并行 4 线程拷贝数据文件至 /backup/full/{日期}/ 目录；\n三、备份完成后自动执行 prepare 校验，并记录 binlog 位点与 GTID 集合；\n四、校验通过后压缩为 qpress 格式并计算 MD5，写入备份登记表；\n五、同步异地：压缩包上传异地对象存储，上传完成后比对 MD5 一致性。\n2.2 备份有效性抽检\n一、每周六随机抽取一份全量备份，在恢复演练环境执行完整恢复；\n二、恢复后运行数据校验脚本：核对核心表行数、抽样 1000 行业务数据checksum、校验账号权限；\n三、抽检结果登记《备份有效性检查表》，恢复失败的备份视为不可用，需立即重新备份并复盘原因。', 193, '2026-08-24 11:37:27');
INSERT INTO `kb_chunk` VALUES (157, '740beabc-11db-4eb7-bec7-a78b98daf973', 24, 7, '三、MySQL 恢复操作手册', '三、MySQL 恢复操作手册\n3.1 场景一：误删除表（数据仍可在备份中找到）\n一、确认误操作时间点与影响的表，立即停止相关业务写入（评估影响后决定）；\n二、从最近一次全量备份恢复出临时实例（端口 3307）；\n三、应用 binlog 至误操作前一秒：mysqlbinlog --start-position=<全量位点> --stop-datetime=<误操作前1秒> | mysql -P 3307；\n四、从临时实例导出误删表数据（mysqldump 单表导出，注意 --single-transaction）；\n五、在主库执行数据回补，回补 SQL 必须经双人复核后执行；\n六、全过程记录时间线，恢复后 24 小时内提交事件报告。\n3.2 场景二：主库宕机快速切换\n一、确认主库故障不可快速恢复后，60 秒内决策是否切换；\n二、在从库中选取数据最新的节点（比对 Exec_Master_Log_Pos）执行 CHANGE MASTER 提升为新主；\n三、应用侧切换数据源地址（配置中心一键切换，生效时间 30 秒内）；\n四、原主库恢复后以新主库为基准重建从库，禁止直接双写回原主库；', 307, '2026-08-24 11:37:27');
INSERT INTO `kb_chunk` VALUES (158, '41608d62-9f19-46e6-87d7-795ab218748b', 24, 8, '三、MySQL 恢复操作手册', '一键切换，生效时间 30 秒内）；\n四、原主库恢复后以新主库为基准重建从库，禁止直接双写回原主库；\n五、切换过程必须留存 show slave status 输出与操作时间戳备查。\n3.3 场景三：整库灾难恢复\n一、申请异地存储中的最新全量备份与全部增量 binlog；\n二、在灾备环境按「全量 → 增量 → binlog 重放」顺序恢复；\n三、以 RTO 60 分钟为目标分解：备份下载 10 分钟、全量恢复 25 分钟、binlog 重放 20 分钟、应用验证 5 分钟；\n四、恢复完成后由业务方执行验收用例，验收通过前不得宣告恢复结束。', 168, '2026-08-24 11:37:27');
INSERT INTO `kb_chunk` VALUES (159, 'd34caeb1-34d3-4acb-aec9-f1555231c440', 24, 9, '四、Elasticsearch 备份与恢复', '四、Elasticsearch 备份与恢复\n4.1 快照策略\n一、决策日志索引每日 01:30 快照至仓库名 ops-snap-repo；\n二、快照保留 30 天，超过自动由 ILM 策略删除；\n三、知识库索引变更（文档重入库）前手动创建一次临时快照，命名前缀 manual-。\n4.2 快照恢复流程\n一、确认目标集群存在同名仓库且版本兼容（高版本快照不可恢复至低版本集群）；\n二、恢复前关闭相关索引，执行 _restore API 时指定 rename_pattern 避免覆盖现有索引；\n三、恢复后检查分片状态为 green、文档数与快照元数据一致方可切流。', 174, '2026-08-24 11:37:27');
INSERT INTO `kb_chunk` VALUES (160, '149d7a8c-9cfa-40bf-af87-3a0554e88109', 24, 10, '五、恢复演练制度', '五、恢复演练制度\n一、季度演练：每季度末组织一次全流程灾难恢复演练，覆盖「核心库全量恢复 + PITR」；\n二、演练环境：独立恢复演练集群，与生产网络隔离；\n三、演练评分：RTO 达标 40 分、数据完整性 40 分、过程规范 20 分，总分低于 80 分需限期整改并复测；\n四、演练报告归档至运维知识库，作为《应急预案》修订输入。', 103, '2026-08-24 11:37:27');
INSERT INTO `kb_chunk` VALUES (161, 'f2d653d1-c678-460d-b617-fe1d5c03b1f0', 24, 11, '六、常见故障与处理', '六、常见故障与处理\n一、备份任务卡死：检查 XtraBackup 进程与磁盘 IO，超过 6 小时未完成的任务 kill 后重跑，并评估窗口期调整；\n二、备份文件 MD5 不一致：判定传输损坏，重新上传，连续损坏需排查备份机磁盘与网络；\n三、binlog 缺失：立即停止该库所有备份任务保留现场，评估数据丢失范围，按 P2 事件处理；\n四、恢复演练数据校验失败：优先排查字符集与 collation 差异（utf8mb4_0900_ai_ci），其次检查表结构 drift。', 147, '2026-08-24 11:37:27');
INSERT INTO `kb_chunk` VALUES (162, 'faf564c1-b174-4c56-82db-1ec50c92d322', 24, 12, '七、附则', '七、附则\n本指南由 DBA 组负责维护，备份脚本、恢复脚本与校验脚本存放于内部仓库 dba-backup 目录。重大恢复操作（涉及核心交易库）执行前必须电话确认值班经理授权，录音留存。', 57, '2026-08-24 11:37:27');
INSERT INTO `kb_chunk` VALUES (163, '5562375a-7434-422b-87a6-c07e52d4c631', 25, 1, '网络故障排查与处理手册/一、排查总体方法论', '网络故障排查与处理手册\n> 文档编号：OPS-NET-2026-003 ｜ 版本：V2.6 ｜ 更新日期：2026-05-12 ｜ 适用角色：网络工程师、值班运维\n一、排查总体方法论\n1.1 分层排查模型\n网络故障排查遵循自底向上的分层定位法，按顺序排查，避免跳层猜测：\n1. **物理层**：线缆、光模块、端口状态（up/down）、CRC 错包；\n2. **链路层**：VLAN 划分、生成树阻塞、链路聚合状态、MAC 地址表；\n3. **网络层**：路由收敛、ARP 表、ICMP 连通性、TTL 异常、MTU 分片；\n4. **传输层**：端口监听、连接状态（SYN_SENT / CLOSE_WAIT 堆积）、防火墙策略；\n5. **应用层**：DNS 解析、证书校验、负载均衡健康检查、应用超时配置。\n1.2 黄金四问\n接到故障报告后，值班工程师必须先确认四个问题再动手：\n- 故障范围：单机、单机房还是全网？（决定影响面定级）\n- 时间特征：持续存在还是间歇出现？何时开始？\n- 变更关联：故障时间点前后是否有网络/系统变更？\n- 复现条件：能否稳定复现，依赖什么路径与协议？', 307, '2026-08-24 11:37:28');
INSERT INTO `kb_chunk` VALUES (164, 'b0ad83ed-d393-4663-89bb-a6a80400696e', 25, 2, '网络故障排查与处理手册/二、常用排查命令速查', '二、常用排查命令速查\n2.1 连通性定位\n| 目的 | 命令 | 关注点 |\n| --- | --- | --- |\n| 链路连通 | `ping -c 100 <target>` | 丢包率、RTT 抖动（单次 ping 无意义） |\n| 路径追踪 | `traceroute -T -p 443 <target>` | 在哪一跳开始异常、是否绕路 |\n| 端口可达 | `telnet <ip> <port>` / `Test-NetConnection` | TCP 是否可建立 |\n| 本地路由 | `ip route get <dst>` | 出接口与下一跳是否符合预期 |\n| ARP 状态 | `arp -n` | ARP 是否为真实网关 MAC（防 ARP 欺骗） |\n2.2 服务器侧网络栈检查\n- `ss -s`：连接总数概览，TIME_WAIT/CLOSE_WAIT 是否异常堆积；\n- `ss -tan state close-wait`：定位 CLOSE_WAIT 对应进程（通常是应用未调用 close）；', 290, '2026-08-24 11:37:28');
INSERT INTO `kb_chunk` VALUES (165, 'f3bbda21-0c8b-443c-b9cb-0c25974b55f6', 25, 3, '网络故障排查与处理手册/二、常用排查命令速查', 'e close-wait`：定位 CLOSE_WAIT 对应进程（通常是应用未调用 close）；\n- `dmesg -T | grep -i nic`：网卡驱动报错、链路抖动记录；\n- `ethtool -S eth0 | grep -iE \'err|drop|discard\'`：网卡级丢包与 CRC 错误计数；\n- `conntrack -S`：连接跟踪表是否打满（满表会导致新建连接随机失败）。', 125, '2026-08-24 11:37:28');
INSERT INTO `kb_chunk` VALUES (166, '0a692e01-3844-4c41-9718-2f06380ffb0a', 25, 4, '网络故障排查与处理手册/三、典型故障处理预案', '三、典型故障处理预案\n3.1 案例 A：单台服务器无法访问外网\n**现象**：应用报连接超时，其他机器正常。\n**排查路径**：\n1. `ping 网关`：不通则检查本机 IP/掩码/网关配置与交换机端口 VLAN；\n2. 网关通但 `ping 8.8.8.8` 不通：核对默认路由与防火墙出网白名单；\n3. IP 通但域名不通：`nslookup` 检查 DNS，切换 223.5.5.5 对比验证；\n4. 均正常但业务端口不通：检查 iptables/nftables 规则与云安全组。\n**常见根因统计**（近 12 个月）：安全组未放行 38%、DNS 配置错误 27%、路由缺失 18%、本机防火墙 12%、其他 5%。\n3.2 案例 B：负载均衡健康检查批量失败\n**现象**：SLB 摘除多台后端，服务容量骤降。\n**处理步骤**：\n1. 立即查看后端机负载：CPU 打满（如 95%+）导致健康检查响应超时，先扩容再排查；\n2. 后端正常则检查健康检查探测路径：`curl -v http://127.0.0.1/healthz`，确认本地可达；', 298, '2026-08-24 11:37:28');
INSERT INTO `kb_chunk` VALUES (167, 'ac1c3002-f3b8-479f-8aa5-72309208b866', 25, 5, '网络故障排查与处理手册/三、典型故障处理预案', '检查探测路径：`curl -v http://127.0.0.1/healthz`，确认本地可达；\n3. 本地可达但 SLB 不通：核对安全组是否放行 SLB 探测网段；\n4. 确认健康检查阈值配置：连续失败次数（建议 3 次）与间隔（建议 2 秒）是否被误改；\n5. 恢复后将阈值改回并检查配置审计日志，定位误操作来源。\n3.3 案例 C：跨机房专线丢包\n**现象**：专线链路丢包 3%，数据库主从延迟告警。\n**处理要点**：\n1. 两端交换机对同一条链路执行 `display transceiver` 与光功率检查：收发光功率是否在阈值内；\n2. 逐段打流测试（iperf3 -P 8），定位丢包发生在运营商段还是机房内段；\n3. 若为运营商侧劣化：立即切换备用专线（BGP 自动切换失败时手动切换），并提交运营商工单要求 4 小时内反馈；\n4. 切换后观察 30 分钟主从延迟追平（Seconds_Behind_Master 归零）再关闭事件。\n3.4 案例 D：DNS 解析间歇失败\n**现象**：偶发「域名无法解析」，重试成功。\n**排查方向**：', 299, '2026-08-24 11:37:28');
INSERT INTO `kb_chunk` VALUES (168, '1530488b-fac2-455c-aacf-f8ec0f3e310c', 25, 6, '网络故障排查与处理手册/三、典型故障处理预案', '案例 D：DNS 解析间歇失败\n**现象**：偶发「域名无法解析」，重试成功。\n**排查方向**：\n1. 客户端侧：`nslookup <domain> <dns_ip>` 分别指定主备 DNS 对比失败率；\n2. DNS 服务侧：检查 dnsmasq/coredns 负载与上游转发超时配置（建议 forward_timeout 2s）；\n3. 检查解析记录 TTL：过短 TTL（低于 30s）在 DNS 抖动时放大失败概率；\n4. 应急措施：核心域名在应用侧配置本地 hosts 兜底或启用 DNS 缓存（systemd-resolved / nscd）。', 174, '2026-08-24 11:37:28');
INSERT INTO `kb_chunk` VALUES (169, '5aa9f5f7-f159-4b9f-8203-9330b47b892c', 25, 7, '网络故障排查与处理手册/四、告警分级与响应要求', '四、告警分级与响应要求\n| 级别 | 定义 | 示例 | 响应/升级时限 |\n| --- | --- | --- | --- |\n| P1 | 全网或核心业务中断 | 机房级断网、核心交换机宕机 | 5 分钟响应，30 分钟内升级 CTO |\n| P2 | 部分业务受损 | 单专线丢包、SLB 异常摘除 | 15 分钟响应，2 小时未恢复升级 |\n| P3 | 无即时影响但存在风险 | 冗余链路单条 down、丢包 0.5% | 当班内处理，24 小时闭环 |\n| P4 | 观察类 | 光功率临界、错误包缓慢增长 | 建跟踪工单，周内评审 |', 170, '2026-08-24 11:37:28');
INSERT INTO `kb_chunk` VALUES (170, '68fd0fe1-b7f3-4135-99ea-2f332287ed09', 25, 8, '网络故障排查与处理手册/五、工具与权限管理', '五、工具与权限管理\n- 网络设备配置修改必须通过堡垒机，保留完整会话录像；\n- 生产网络设备只允许运维组与网络组成员登录，账号每季度审计一次；\n- 抓包排障（tcpdump）只允许在目标服务器执行，抓包文件可能包含敏感数据，分析完毕 48 小时内删除；\n- 每次故障处置后 3 个工作日内补充/更新本手册案例库，由网络组周会评审合入。', 104, '2026-08-24 11:37:28');
INSERT INTO `kb_chunk` VALUES (171, '261395b3-29d0-4231-9e93-2fb1a6c853c9', 25, 9, '网络故障排查与处理手册/六、变更记录', '六、变更记录\n- V2.6（2026-05-12）：新增 DNS 间歇失败案例与 conntrack 打满检查项。\n- V2.3（2026-02-08）：告警分级表对齐公司 P1-P4 事件标准；增加案例根因统计。\n- V2.0（2025-11-30）：全面重写为分层排查模型结构。', 87, '2026-08-24 11:37:28');
INSERT INTO `kb_chunk` VALUES (172, 'a2cfb8d3-cfbb-42c7-901a-5cbf605b6956', 26, 1, '第一章 总则', '信息安全应急响应预案\n第一章 总则\n文档编号：SEC-IR-2026-005。版本：V3.4。发布日期：2026年3月30日。批准人：安全委员会\n。密级：秘密。本预案适用于公司全部信息系统发生或可能发生信息安全事件时的应急响应工作\n。', 73, '2026-08-24 11:37:29');
INSERT INTO `kb_chunk` VALUES (173, '0e076a0f-846c-4bb5-98c6-103aec0a7ff9', 26, 2, '第二章 事件分级', '第二章 事件分级\n一、分级标准\n一级（特别重大）：核心业务系统全面瘫痪超过四小时，或泄露客户敏感数据超过十万条，\n或造成直接经济损失超过五百万元。二级（重大）：核心业务部分中断超过一小时，或内部数据\n泄露超过一万条，或数据被篡改影响对外服务。三级（较大）：单一系统故障、发现高危漏洞被\n利用迹象、少量内部数据异常泄露。四级（一般）：单点病毒感染、钓鱼邮件被拦截、扫描探测\n行为。\n二、响应时限要求\n一级事件：十分钟内值班安全工程师确认，三十分钟内成立应急指挥部，一小时内向总经理\n与安全委员会书面报告。二级事件：三十分钟内确认，两小时内报告安全负责人。三级事件：两\n小时内确认，当日内处置完毕并记录。四级事件：值班内处置，工单跟踪闭环。', 197, '2026-08-24 11:37:29');
INSERT INTO `kb_chunk` VALUES (174, '860dc41d-637c-4610-8427-04e77186e7a7', 26, 3, '第三章 应急组织', '第三章 应急组织\n应急指挥部由安全负责人任总指挥，成员包括安全组、运维组、研发中心代表、法务合规与\n公关代表。下设四个职能小组：一、监测研判组：负责事件确认、影响评估与取证固证；二、处\n置组：负责抑制、根除与恢复实施；三、沟通组：负责内部通报与对外口径管理；四、法务组：\n负责监管报送与证据链合规审查。', 94, '2026-08-24 11:37:29');
INSERT INTO `kb_chunk` VALUES (175, '562a41bb-16ef-4da2-a774-5560fce4a3b9', 26, 4, '第四章 标准响应流程', '第四章 标准响应流程\n一、准备阶段\n日常准备包括：资产台账季度更新（覆盖全部域名、IP、系统与责任人）、应急预案年度演\n练不少于两次、备份有效性按《数据库备份与恢复指南》抽检、堡垒机与日志平台全量覆盖、蜜\n罐与入侵检测规则月度评审。\n二、检测与研判\n接报或告警后，值班工程师十分钟内完成初步研判：确认事件真实性、影响系统范围、初步\n定级。研判证据（流量截图、日志片段）立即固化到只读存储。定级有争议时按就高原则先响应\n后调整。\n三、抑制阶段\n抑制措施按影响从小到大依次考虑：封禁攻击源 IP、下线受影响服务、切断异常外联、关闭\n相关端口、账号强制下线与改密、必要时断开互联网出口。执行任何抑制操作前须在处置群同步\n并留下操作记录，重大动作需总指挥确认。\n四、根除与恢复\n根除阶段须找到入侵入口并彻底清除：清理后门账户与定时任务、重装被控主机、更换全部\n可能泄露的凭证与密钥。恢复按「备份恢复、灰度验证、全量切流」三步执行，恢复后连续观察\n四十八小时。恢复期间业务降级方案由处置组同步准备。\n五、复盘阶段\n一二级事件恢复后五个工作日内召开复盘会，产出事件报告：完整时间线、根因分析、损失\n评估、责任认定、改进措施（落实到人）。改进措施纳入安全组季度任务跟踪，完成情况在安全\n委员会汇报。', 336, '2026-08-24 11:37:29');
INSERT INTO `kb_chunk` VALUES (176, 'dbad232d-1b86-43f0-bcb0-d08665bebaa5', 26, 5, '第五章 专项处置预案', '第五章 专项处置预案\n一、勒索软件专项\n发现勒索加密行为立即断网不断电（保留内存证据），隔离同网段其他主机，禁止支付赎金\n；评估备份可用性后按备份体系重建。全部密钥类凭证（数据库密码、API Key、SSH\n私钥）视为已泄露并强制轮换。\n二、数据泄露专项\n确认泄露范围后两小时内完成：泄露数据类型与数量评估、泄露通道定位、阻断。涉及客户\n个人信息超过一万条的，法务组按监管要求评估上报义务，对外口径由公关统一管理，任何个人\n不得私自回应。\n三、DDoS 攻击专项\n联系运营商启动流量清洗，切换高防 IP，非核心服务临时下线保障核心链路带宽；攻击结束\n后保留完整攻击流量样本用于加固规则。单次攻击峰值超过 10Gbps 自动升级为二级事件。\n四、内部违规专项\n员工违规导出数据、越权访问等内部事件由安全组与人力资源部联合调查，涉及劳动合同解\n除或司法移送的由法务组主导。调查期间相关人员账号暂停但数据保留。', 249, '2026-08-24 11:37:29');
INSERT INTO `kb_chunk` VALUES (177, '81274cac-3ec2-4339-8d1a-b93de066c14c', 26, 6, '第六章 上报矩阵', '第六章 上报矩阵\n一级事件上报链：值班工程师、安全负责人、总经理、监管机构（如适用）。二级事件上报\n链：值班工程师、安全负责人。三级及以下事件在安全周报中汇总上报。任何级别事件涉及客户\n合同约定的，由客户成功部按合同约定时间窗口同步客户。', 74, '2026-08-24 11:37:29');
INSERT INTO `kb_chunk` VALUES (178, 'c289262b-d4f2-47ee-aa40-9cc4eed6de51', 26, 7, '第七章 演练与维护', '第七章 演练与维护\n每半年至少一次红蓝对抗演练，每年至少一次全要素实战演练（含勒索与数据泄露场景）。\n演练后十个工作日内更新预案。预案联系人通讯录每月校对一次，人员变动时即时更新。本预案\n由安全组负责解释。', 64, '2026-08-24 11:37:29');
INSERT INTO `kb_chunk` VALUES (179, '3cb3303e-517e-4bea-88bd-eb431d640264', 27, 1, '一、总则', '账号权限管理与审计规范\n一、总则\n文档编号：SEC-ACC-2026-006。版本：V2.8。发布日期：2026 年 4 月 15 日。本规范适用于公司全部信息系统的账号、权限与操作审计管理，覆盖员工、外包人员与系统账号。', 69, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (180, '3000051e-d742-468f-a967-fc0243da238f', 27, 2, '二、账号生命周期', '二、账号生命周期\n2.1 创建\n员工账号由 HR 入职流程自动触发创建，入职当日开通邮箱、OA 与统一认证账号；业务系统权限由部门负责人在入职工单中勾选角色模板。外包人员账号必须以 wb- 前缀命名并设置与合同一致的到期日，到期自动禁用。禁止共享账号与借用账号。\n2.2 变更\n转岗员工的旧岗位权限在转岗生效日自动回收，新权限按新岗位角色模板重新申请；跨部门转岗需双方部门负责人确认。权限提升（如获得生产库写权限）须说明事由并经权限审批流（直属上级加系统负责人两级）批准。\n2.3 回收\n离职当日十七点前完成全部系统账号禁用，门禁同步失效；核心系统（生产环境、数据库、代码仓库）账号在离职面谈完成前即可先行禁用。离职账号数据归档保留九十天后清理。连续六十天未登录的休眠账号自动禁用，恢复需重新申请。', 216, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (181, 'adb3a15c-ca43-48b8-87b5-d9ac31a50038', 27, 3, '三、权限模型', '三、权限模型\n系统统一采用基于角色的访问控制（RBAC）：权限授予角色，角色授予人。角色设计遵循最小权限原则，默认拒绝。每个系统须定义三类基础角色：只读（查询类岗位）、操作（日常业务处理）、管理（配置与授权）。高危权限（数据导出、批量删除、密钥管理）独立成角色，单独审批且默认有效期三十天，到期自动回收可续期。\n3.1 权限矩阵维护\n各系统负责人维护《权限矩阵表》（角色、权限点、岗位映射），每季度评审一次。评审内容：角色与权限点是否仍必要、是否存在越权配置、高危权限持有人清单。评审结果报安全组备案。', 156, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (182, '950419d4-d1df-43b9-9df9-e9c1e37e6f11', 27, 4, '四、特权账号管理', '四、特权账号管理\nroot、数据库管理员、云平台主账号等特权账号纳入堡垒机统一纳管，禁止直连。特权操作必须双人复核（操作人加复核人在线确认）。生产环境例行维护使用临时授权：值班场景申请四小时临时特权窗口，到期自动降权。特权账号口令每季度轮换，轮换记录加密保存。break-glass 紧急口令密封保存在安全组双人保管的信封中，启用后二十四小时内必须轮换并复盘。', 112, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (183, '7a7711b0-b3dc-4814-95cd-0acb3d84f8f5', 27, 5, '五、认证与密码策略', '五、认证与密码策略\n统一认证支持密码加多因素认证（MFA），以下场景强制 MFA：特权账号、VPN 拨入、生产环境访问、财务与人力系统。密码规则：长度不少于十二位，包含大小写字母、数字与特殊字符，九十天强制更换，不得与最近五次历史密码重复。连续五次登录失败锁定账号三十分钟。禁止在代码、配置文件与即时通讯中明文存储任何口令，密钥统一使用密钥管理服务。', 108, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (184, '4d96f02b-3754-418f-9ad7-a604fbd54a96', 27, 6, '六、操作审计', '六、操作审计\n6.1 审计范围\n必须审计的操作：登录登出、权限变更、数据导出与批量删除、生产环境命令执行、配置修改、密钥使用。审计日志包含：时间、操作人、源地址、操作对象、动作、结果与请求标识。日志实时外发至独立审计平台，任何人（包括系统管理员）无权限删除或修改审计记录。\n6.2 日志留存与分析\n审计日志在线保留一百八十天，冷存储保留两年，满足监管审计需要。安全组每周输出《高危操作周报》：非工作时间特权操作、异常批量导出、权限变更异常波动。发现可疑操作两个工作日内完成核查并反馈结论。\n6.3 定期审计检查\n每季度开展权限合规审计：抽查百分之十在职员工权限与岗位匹配性、全量核对特权账号持有人、清点离职未禁用账号。审计发现的问题限期整改，整改率纳入部门安全考核。', 206, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (185, '23275a69-49fe-4263-98c0-66b0555709a5', 27, 7, '七、第三方与机器人账号', '七、第三方与机器人账号\n系统集成使用的 API 账号按系统命名（如 svc-rag-etl），权限限定到最小接口集合，凭证每半年轮换。自动化机器人账号禁止拥有交互式登录能力。第三方合作方访问一律通过临时账号加白名单 IP，合作结束后立即回收并出具访问记录。', 79, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (186, '9d1a0692-e99c-4b97-8187-8f25256503d2', 27, 8, '八、附则', '八、附则\n本规范由安全组负责解释与修订，自 2026 年 4 月 15 日起施行，原 V2.5 版本同时废止。违反本规范造成安全事件的，按公司奖惩制度与《信息安全应急响应预案》相关条款处理。', 59, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (187, '43344004-9a8f-4a55-a31c-50964f8cece2', 28, 1, '一、巡检体系总览', '服务器巡检与日常运维手册\n文档编号：OPS-SRV-2026-001\n版本：V4.1\n发布日期：2026年4月5日\n适用范围：生产环境全部物理机、虚拟机与容器宿主机\n一、巡检体系总览\n1.1 巡检分级\n一、日常巡检：每个工作日 9:30 前完成，由当日值班工程师执行；\n二、周度巡检：每周五 16:00 前完成，由运维组长复核确认；\n三、月度深度巡检：每月最后一个工作日完成，输出《月度巡检报告》并归档；\n四、节假日前专项巡检：重大节假日前两个工作日内完成，重点核查容量与应急预案就绪状态。\n1.2 巡检范围清单\n一、计算资源：共 86 台服务器，其中物理机 32 台、虚拟机 41 台、容器宿主机 13 台；\n二、存储资源：3 套分布式存储集群、2 台 NAS（总容量 480TB，已用 62%）；\n三、数据库：MySQL 主从集群 6 套（核心交易库为一主两从）、Redis 哨兵集群 3 套；\n四、中间件：Kafka 集群（8 节点）、RabbitMQ 集群（3 节点）、Elasticsearch 集群（6 节点）；\n五、网络设备：核心交换机 4 台、接入交换机 28 台、防火墙 6 台、负载均衡 4 台。', 315, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (188, '51d174f3-2190-4b5b-bf79-6d7d08cb4884', 28, 2, '二、主机层巡检项目与阈值', '二、主机层巡检项目与阈值\n2.1 每日必检项目\n一、CPU 使用率：告警阈值 80%，持续 5 分钟触发 P3 告警；连续 10 分钟超过 90% 升级为 P2 告警；\n二、内存使用率：告警阈值 85%；swap 使用超过 1GB 需要记录并分析；\n三、磁盘使用率：告警阈值 80%，85% 触发强制清理评估，90% 立即执行紧急扩容流程；\n四、磁盘 inode 使用率：告警阈值 80%，小文件堆积常导致 inode 先于空间耗尽；\n五、系统负载（load average）：告警阈值为 CPU 核数的 1.5 倍；\n六、僵尸进程数量：超过 10 个需要定位父进程并处理。\n2.2 每周加检项目', 185, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (189, '536c4b52-5dd6-41b3-85c8-10c649ba9ea8', 28, 3, '一、文件系统只读检查：dmesg 与 /var/log/messages 中检索 read-only 关键字；', '一、文件系统只读检查：dmesg 与 /var/log/messages 中检索 read-only 关键字；\n二、时间同步状态：所有节点 NTP 偏差必须小于 50 毫秒，偏差超标会导致集群证书校验失败；', 64, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (190, '43cfe9db-44a4-4578-b109-975acd16fe16', 28, 4, '三、内核日志错误：检查 oom-killer、I/O error、segfault 等关键字；', '三、内核日志错误：检查 oom-killer、I/O error、segfault 等关键字；\n四、登录安全审计：last 与 lastb 输出，关注非工作时间 root 登录与失败登录超过 20 次的 IP；\n五、证书有效期：TLS 证书剩余有效期不足 30 天进入续期流程，不足 7 天升级为 P2 事件。\n2.3 性能基线参考\n生产应用服务器性能基线（每日峰值的 7 日均值）：\n一、应用服务器：CPU 均值 45%，内存均值 70%，磁盘 util 低于 40%；\n二、数据库服务器：CPU 均值 55%，慢查询（超过 1 秒）每日不超过 50 条；\n三、容器宿主机：Pod 重启次数每日不超过 3 次，镜像磁盘占用不超过 60%；\n四、任何节点连续三天偏离基线 20% 以上，需要提交容量分析报告。', 219, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (191, 'df26378f-25d2-4721-a90a-d00132f77adf', 28, 5, '三、数据库巡检要点', '三、数据库巡检要点\n3.1 MySQL 日常检查项\n一、主从延迟：Seconds_Behind_Master 持续大于 5 秒触发 P3 告警，大于 60 秒升级 P2；\n二、连接数：Threads_connected 超过 max_connections 的 80% 需要排查连接泄漏；\n三、慢查询：开启 slow_query_log（阈值 1 秒），每周汇总 Top 10 慢查询交由研发优化；\n四、备份状态：每日全量备份 02:00 执行，校验备份文件大小与 binlog 完整性，备份成功率必须为 100%；\n五、表空间增长：核心表日增长超过 5GB 需评估分库分表或归档方案。\n3.2 Redis 检查项\n一、内存碎片率：mem_fragmentation_ratio 超过 1.5 需要评估内存碎片整理；\n二、持久化状态：RDB 最近一次保存是否成功，AOF 重写是否频繁阻塞；\n三、热 Key 与大 Key：单 Key 超过 10KB 或 QPS 超过 5000 的 Key 登记到治理清单；\n四、主从切换演练：每季度一次，切换期间业务损失评估结果归档。', 300, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (192, '47d73e9b-a8e0-42e9-bba3-5cf33bf348b7', 28, 6, '四、网络与安全巡检', '四、网络与安全巡检\n4.1 网络设备检查\n一、端口流量：任意链路带宽利用率超过 70% 触发扩容评估；\n二、丢包率：核心链路丢包率必须低于 0.01%，超标立即排查光模块与光纤；\n三、设备温度：核心交换机温度超过 45 摄氏度检查机房制冷；\n四、配置备份：每周日自动备份全部网络设备配置，配置变更后立即备份一次。\n4.2 安全巡检基线\n一、漏洞修复：高危漏洞 7 天内完成修复，中危 30 天内，低危随版本迭代处理；\n二、补丁管理：每月第二个周二统一评估安全补丁，生产环境灰度验证后分批上线；\n三、端口开放审计：每季度核对一次防火墙策略，无工单依据的临时策略一律关闭；\n四、基线核查：新上线服务器必须通过基线加固模板核查（关闭密码登录、限制 sudo、安装 HIDS agent）方可接入生产。', 215, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (193, 'acf53e81-84ca-4a2f-887e-60f5f180cab3', 28, 7, '五、变更与值班管理', '五、变更与值班管理\n5.1 变更窗口\n一、常规变更窗口：每周二、四 22:00-24:00；\n二、封网期：每月月底最后三天、重大节假日（国庆、春节）前一周禁止非紧急变更；\n三、变更审批：标准变更双人复核，重大变更需技术委员会评审并准备回滚方案；\n四、变更成功率目标：98% 以上，失败复盘报告三个工作日内提交。\n5.2 值班制度\n一、值班分组：主值、副值、经理备班三级；\n二、响应时限：P1 事件电话呼叫 5 分钟内响应，P2 事件 15 分钟内响应；\n三、交接班：每日 9:30 站会交接，未闭环事件必须书面移交；\n四、值班手机与 VPN：值班期间保持值班手机畅通，VPN 连接可用性每日自检一次。', 186, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (194, '5daf9849-9520-411b-b579-ad1ca0b5dd59', 28, 8, '六、巡检结果处理', '六、巡检结果处理\n一、巡检发现的问题统一录入工单系统，按 P1-P4 定级并指定责任人；\n二、巡检数据全部汇入监控大盘，趋势类问题（磁盘缓慢增长等）建立容量跟踪表；\n三、《月度巡检报告》包含：巡检完成率、发现问题描述、闭环率（目标 95%）、容量趋势与建议；\n四、连续两个月同类问题重复出现的，升级为专项治理项目，由运维经理牵头闭环。', 104, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (195, 'a83f2e2d-ef28-45cf-8059-72753f30af50', 28, 9, '七、附则', '七、附则\n本手册由运维组维护，每季度修订一次。巡检表单模板、基线加固脚本与告警阈值配置统一存放在内部代码仓库 ops-runbook 目录，以仓库版本为准。', 48, '2026-08-24 11:37:30');
INSERT INTO `kb_chunk` VALUES (196, '58f4ddc1-1c35-469b-9819-b2fbf4066cd8', 29, 1, '监控告警体系配置规范/一、监控分层架构', '监控告警体系配置规范\n> 文档编号：OPS-MON-2026-004 ｜ 版本：V2.2 ｜ 更新日期：2026-06-01 ｜ 适用范围：全量生产服务、中间件、数据库与网络设备\n一、监控分层架构\n1.1 指标采集分层\n监控体系按四层采集，所有指标统一汇入 Prometheus 集群（2 副本高可用），告警经 Alertmanager 分发：\n| 层级 | 采集方式 | 抓取间隔 | 典型指标 |\n| --- | --- | --- | --- |\n| 基础设施层 | node_exporter | 15s | CPU、内存、磁盘、网络 |\n| 中间件层 | 各类 exporter | 15-30s | MySQL/Redis/Kafka/ES 指标 |\n| 应用层 | 应用内置 /metrics | 30s | QPS、错误率、P99 延迟、GC |\n| 业务层 | 自定义上报 | 60s | 订单量、支付成功率、问答准确率 |\n1.2 指标命名规范\n- 格式：`<域>_<对象>_<指标>_<单位>`，如 `app_chat_first_token_ms_p95`；', 304, '2026-08-24 11:37:31');
INSERT INTO `kb_chunk` VALUES (197, '0c2c6ded-f8c2-4f48-8fb5-9a59c0b17009', 29, 2, '监控告警体系配置规范/一、监控分层架构', '_<对象>_<指标>_<单位>`，如 `app_chat_first_token_ms_p95`；\n- 禁止使用无语义命名（如 metric1）；新增指标必须登记《指标字典》；\n- Label 规范：必须携带 `env`（prod/pre）、`cluster`、`instance`；禁止在 label 中使用用户 ID 等高基数值。', 104, '2026-08-24 11:37:31');
INSERT INTO `kb_chunk` VALUES (198, 'fce98909-8adf-44fa-b7ed-bc125ccdcd1a', 29, 3, '监控告警体系配置规范/二、核心告警规则', '二、核心告警规则\n2.1 基础资源告警\n| 规则 | 表达式（示意） | 持续时间 | 级别 |\n| --- | --- | --- | --- |\n| CPU 使用率过高 | node_cpu_util > 0.90 | 10m | P3 |\n| 内存使用率过高 | mem_util > 0.92 | 5m | P3 |\n| 磁盘空间不足 | disk_free_pct < 0.10 | 5m | P2 |\n| 磁盘预测耗尽 | 预测 48h 内写满 | - | P2 |\n| 节点不可达 | up == 0 | 1m | P2（核心节点 P1） |\n2.2 应用服务告警\n1. **可用性**：健康检查失败或 Pod 重启超过 3 次 → P2；核心服务（对话、检索）不可用 → P1；\n2. **错误率**：HTTP 5xx 比例超过 1% 持续 5 分钟 → P3；超过 5% → P2；\n3. **延迟**：对话接口首 token P95 超过 4 秒持续 10 分钟 → P3；', 277, '2026-08-24 11:37:31');
INSERT INTO `kb_chunk` VALUES (199, 'b49a884e-e18d-434f-8e0a-efe54ec069c2', 29, 4, '监控告警体系配置规范/二、核心告警规则', '2；\n3. **延迟**：对话接口首 token P95 超过 4 秒持续 10 分钟 → P3；\n4. **饱和度**：工作队列积压超过 1000 或消费者 lag 超过 50000 持续 15 分钟 → P3。\n2.3 数据库与中间件告警\n- MySQL 主从延迟大于 60 秒 → P2；连接数使用率超过 85% → P3；\n- Redis 内存使用率超过 90% 或主从断连 → P2；\n- Kafka 消费组 rebalance 频繁（每小时超过 3 次）→ P3；\n- ES 集群状态 yellow 超过 30 分钟 → P3，red → P1；分片未分配 → P2。', 180, '2026-08-24 11:37:31');
INSERT INTO `kb_chunk` VALUES (200, '4d775e5b-cfaf-48b0-af37-f930c538c38f', 29, 5, '监控告警体系配置规范/三、告警分级与值班路由', '三、告警分级与值班路由\n3.1 分级标准\n- **P1（灾难）**：核心业务全面不可用，需立即电话叫醒多人响应；\n- **P2（严重）**：业务明显受损或冗余尽失，值班工程师立即处理；\n- **P3（警告）**：存在劣化趋势，当班处理；\n- **P4（提示）**：仅 IM 群通知，进工单跟踪。\n3.2 通知路由矩阵\n| 级别 | 通知渠道 | 响应要求 |\n| --- | --- | --- |\n| P1 | 电话（值班+经理+负责人） + IM 应急群 | 5 分钟内响应 |\n| P2 | 电话（值班） + IM 值班群 | 15 分钟内响应 |\n| P3 | IM 值班群 + 工单 | 2 小时内跟进 |\n| P4 | 工单自动创建 | 按排期处理 |\n静默规则：同一告警组 15 分钟内只通知一次；维护窗口（变更单审批通过）自动静默；禁止手工 silence 超过 24 小时，超时须值班经理审批。\n3.3 升级机制\nP1 告警 30 分钟未确认自动升级通知 CTO；P2 告警 2 小时未恢复升级为值班经理跟进；升级事件必须在事后复盘中说明响应超时原因。', 301, '2026-08-24 11:37:31');
INSERT INTO `kb_chunk` VALUES (201, '50bfdb0c-9461-4dec-9019-76fcb71e9302', 29, 6, '监控告警体系配置规范/四、告警质量治理', '四、告警质量治理\n4.1 噪音控制目标\n- 周告警总量环比波动超过 30% 需要专项分析；\n- 告警有效率（触发后确需人工处理的占比）目标不低于 70%；\n- 月度告警复盘会输出规则优化清单：合并重复规则、收紧持续时间、降级低价值告警。\n4.2 新增告警规则流程\n1. 提交人填写《告警规则申请单》：指标、阈值、级别、理由、预期频率；\n2. 运维组周会评审（重点评估是否会变成噪音源）；\n3. 先以 P4 观察 7 天，确认触发频率合理后调整到正式级别；\n4. 规则入库统一 Git 管理，任何修改必须走 MR 评审，禁止在页面上直接改规则。', 168, '2026-08-24 11:37:31');
INSERT INTO `kb_chunk` VALUES (202, '01e875f1-f603-408b-9e8f-1c2fe3079cc2', 29, 7, '监控告警体系配置规范/五、值班与闭环', '五、值班与闭环\n- 值班表每月 25 日前排定下月，主值/副值轮换，交接班须同步未闭环告警；\n- 所有 P1/P2 告警必须关联事件单，处置过程记录时间线，恢复后 3 个工作日内完成复盘；\n- 复盘产出四要素：时间线、根因、改进项（落实到人）、验证方式；改进项完成率纳入运维组季度考核，目标 90% 以上。', 95, '2026-08-24 11:37:31');
INSERT INTO `kb_chunk` VALUES (203, 'ddc96626-2fc9-4a6f-a7b0-9fcaf546b1e8', 29, 8, '监控告警体系配置规范/六、变更记录', '六、变更记录\n- V2.2（2026-06-01）：新增磁盘预测耗尽告警；明确高基数 label 禁令。\n- V2.1（2026-03-15）：告警规则迁移至 Git 管理；新增静默时长限制。\n- V2.0（2025-12-20）：分级标准对齐公司事件管理规范，新增升级机制。', 86, '2026-08-24 11:37:31');
